import type { D1AuthoredBank } from '../corpus'

export const LEMBAH_AWAN_D_R3: D1AuthoredBank = {
  universeId: 'lembah-awan',
  rubricId: 'D-R3',
  STRONG: [
    { chapters: [
      { chapterNumber: 33, title: 'Patok Air Dipindah', paragraphs: ['Patok pembagi di mulut saluran sudah bergeser dua petak ke bawah ketika Vina memeriksanya pagi itu. Aliran yang semestinya masuk ke persemaiannya berbelok ke kebun milik kantor. Ia menyeret patok kembali ke lubang lama, lalu tiga kru datang membawa cangkul dan menancapkannya di tempat baru. “Ajukan surat kalau mau giliran lamamu,” kata salah satu sambil menekan tanah dengan tumit.'] },
      { chapterNumber: 34, title: 'Permohonan Kehilangan Cap', paragraphs: ['Petugas menerima surat permohonan itu, membaca dua baris, lalu mengembalikannya sebab cap dusun dianggap terlalu pucat. Kepala dusun berangkat ke kota selama tiga hari. Di lereng, satu bedeng semai mulai menguning pada ujung daunnya. Vina memikul dua ember dari pancuran rumah, tetapi tanjakan yang licin menumpahkan separuh isinya sebelum ia mencapai pematang atas.'] },
      { chapterNumber: 35, title: 'Ember Dilarang Melintas', paragraphs: ['Sebuah papan dipaku di mulut jalan kantor: dilarang memikul ember karena tanah dianggap licin. Jalur pengganti memutar tiga teras. Vina mengangkut dua ember sampai bahunya memar, kemudian berhenti di persimpangan dan menyiram bedeng milik warga yang harus ditanam esok. Daun muda di petaknya menggulung ke dalam sepanjang siang.'] },
      { chapterNumber: 36, title: 'Jatah Pancuran Dipotong', paragraphs: ['Bagas mencatat pancuran rumah Vina sebagai pemakaian kebun dan memangkas jatah keluarga satu tempayan. Danu pulang berkeringat dari petikan dan tidak mendapat air untuk membasuh badan. Di dapur, isi kendi hanya cukup untuk satu keperluan. Vina menanak singkong dengan takaran paling irit, menyisihkan sisanya bagi semai, lalu mengelap lantai memakai kain yang sama tiga kali.'] },
      { chapterNumber: 37, title: 'Kendi Pecah di Lereng', paragraphs: ['Kru berdiri melintang di jalan sempit sehingga Vina terdorong ke tepi. Kendi lepas dari lengannya, pecah pada batu, dan air terakhir merembes ke lumpur. Salah seorang menawarkan tambahan satu jam aliran asalkan surat permohonan dicabut. Vina menggeleng, memungut pecahan besar, lalu meminjam kendi Bu Ningsih dengan janji mengganti sebelum pasar Sabtu tutup.'] },
      { chapterNumber: 38, title: 'Harga Kendi Naik', paragraphs: ['Longsor di jalan bawah membuat pasar hanya menyisakan kendi besar seharga dua kali lipat. Vina menjual satu bakul daun petikan untuk menebusnya. Di kusen rumah sudah menempel tagihan pemakaian pancuran, ditulis dengan tinta tebal. Pada barisnya yang terakhir tertera: apabila belum lunas Senin, kartu jatah air rumah ditahan sampai pemeriksaan selesai.'] },
      { chapterNumber: 39, title: 'Kartu Rumah Ditahan', paragraphs: ['Senin pagi petugas mengetuk sebelum uang terkumpul dan mengambil kartu jatah air dari paku dekat pintu. Danu meminjam seember dari tetangga untuk menanak, lalu tetangga itu menerima peringatan agar tidak lagi membagi giliran. Vina berjalan ke balai kecamatan membawa berkasnya. Dua kru mengikuti dari jarak sepuluh langkah sambil mencatat rumah mana yang memberinya minum.'] },
      { chapterNumber: 40, title: 'Saksi Menutup Pintu', paragraphs: ['Tiga tetangga menutup daun pintu ketika Vina meminta tanda tangan tentang patok yang digeser. Seorang menyodorkan surat edaran melalui celah: pembagi air kepada keluarga tanpa kartu kehilangan satu giliran. Hanya Bu Ningsih membubuhkan namanya. Petugas mencoret nama guru itu karena bukan pemilik petak, lalu menjadwalkan pemindahan patok terakhir dari lahan Vina esok pagi.'] },
      { chapterNumber: 41, title: 'Papan Giliran Dipaku', paragraphs: ['Mandor Bagas memaku papan jadwal baru di dekat gerbang, lalu memotong jatah petak Vina menjadi satu jam. Enam penanam menunggu di belakangnya sambil membawa cangkul. Vina melihat namanya paling bawah dan menyadari air akan habis sebelum mencapai kebunnya. Ia menyalin susunan jadwal itu pada sobekan kantong pupuk sebelum hujan menghapus kapur dari papan.'] },
      { chapterNumber: 42, title: 'Salinan Kapur Dirampas', paragraphs: ['Vina membuka sobekan kantong pupuk itu di depan kepala dusun. Seorang kru merampasnya di tangga balai, menyobeknya menjadi empat, kemudian menghapus papan aslinya sebelum hujan turun. Bu Ningsih masih hafal urutan nama, namun Bagas menyatakan kesaksian guru tidak berlaku tanpa cap kantor pengairan. Vina memunguti potongan kertas dari anak tangga; kapurnya sudah luntur pada jari.'] },
      { chapterNumber: 43, title: 'Tiga Petak Mulai Retak', paragraphs: ['Dua hari kemudian tanah di tiga petak Vina membuka retak panjang, sedangkan saluran menuju lereng atas dijaga seorang kru dengan bambu. Danu menawarkan air dari bak mandi mereka, tetapi jumlahnya hanya cukup untuk satu baris semai. Vina memilih menyiram persemaian warga janda terlebih dahulu. Saat pulang, daun teh di kebunnya sendiri sudah melipat di bawah matahari.'] },
      { chapterNumber: 44, title: 'Daun Teh Dijual Murah', paragraphs: ['Pengepul membuka bakul Vina, meraba tepi daun yang kering dan terlipat, lalu menyebut harga separuh. Uang di telapak tangannya hanya menutup ongkos kendi pinjaman, sedangkan tagihan pancuran masih utuh. Bagas menyusul di gerbang dan menjanjikan giliran lama kembali asalkan catatan Bu Ningsih diserahkan kepadanya. Menjelang petang, ujung satu petak lagi berubah cokelat.'] },
      { chapterNumber: 45, title: 'Balai Menolak Aduan', paragraphs: ['Vina memikul sekeranjang daun rusak ke balai, tetapi kunci sudah dipasang begitu kru melihatnya menaiki tangga. Kertas pengumuman di daun pintu menyebut aduan air hanya diterima lewat kantor Bagas mulai esok. Bu Ningsih menitipkan salinan kesaksian pada seorang murid. Petugas menahan kartu sekolah anak itu di meja jaga sampai surat tersebut ditarik.'] },
      { chapterNumber: 46, title: 'Gerbang Dikunci Menjelang Malam', paragraphs: ['Setelah Vina membawa salinan papan jadwal ke balai, Bagas mengunci gerbang utama sebelum matahari tenggelam dan menyatakan semua permintaan air ditunda sampai pemeriksaan selesai. Dua belas keluarga kehilangan aliran malam itu. Warga mendatangi rumah Vina membawa ember kosong dan kemarahan yang bercampur takut. Ia membuka lumbung untuk membagikan benih tahan kering, meski persediaan itu seharusnya untuk musim berikutnya.'] },
      { chapterNumber: 47, title: 'Benih Cadangan Dibagikan', paragraphs: ['Vina menakar benih tahan kering ke dalam dua belas bungkus daun, menyisakan segenggam bagi petaknya. Pagi berikutnya Bagas berdiri di jalan dan menyebut penerima benih tanpa izin tidak akan menerima aliran setelah gerbang dibuka. Empat keluarga meletakkan bungkusan kembali di teras Vina malam itu. Delapan lainnya justru meminta ia ikut menanam sebelum tanah mengeras saat fajar.'] },
      { chapterNumber: 48, title: 'Cangkul Disita Lereng', paragraphs: ['Sebelum fajar kru mendatangi petak, merampas cangkul warga yang sudah berkumpul, dan memuatnya ke gerobak kantor. Vina melubangi tanah memakai jemari sampai kukunya berdarah dan tanah masuk ke luka. Gerbang tetap terpalang, sementara gumpalan hujan di puncak bergerak menjauh. Bagas menetapkan batas tengah hari: penanaman berhenti, atau lumbung Vina digeledah.'] },
      { chapterNumber: 49, title: 'Lumbung Dikosongkan Paksa', paragraphs: ['Vina tetap menanam sampai matahari tinggi. Menjelang siang petugas menyeret seluruh karung keluar dan menumpuknya di halaman berkabut. Warga berdiri berderet menutupi tumpukan itu dengan tikar dan kain gendong. Bagas menarik daun gerbang selebar satu jengkal, cukup untuk satu saluran, lalu menyuruh mereka menunjuk petak mana yang boleh diselamatkan.'] },
      { chapterNumber: 50, title: 'Satu Saluran Dipilih', paragraphs: ['Warga mengarahkan aliran setipis itu ke persemaian bersama dan bukan ke kebun siapa pun. Lahan Vina kering dari ujung ke ujung. Setelah petugas turun, delapan keluarga memikul karung kembali ke dalam lumbung. Danu menghitung batang yang mati di kebun mereka dengan suara datar, sedangkan pada bedeng yang dilubangi jemari muncul tunas sepanjang kuku.'] },
    ], justification: 'Bab 33–50 moves from a shifted marker to blocked buckets, household ration loss, withheld cards, silenced witnesses, a one-hour schedule, guarded channels, and a twelve-family lockout. Vina spends her crop, reserve seed, tools, and warehouse security to keep one shared nursery alive.' },
    { chapters: [
      { chapterNumber: 33, title: 'Debu Hitam Terlihat', paragraphs: ['Debu hitam menempel pada lantai papan di bawah rak benih dan Vina menyapunya ke atas selembar kertas. Karsa mengendus kertas itu di terasnya, lalu meminta segenggam butir dari karung rak paling atas untuk dibelah. Belum sempat mereka naik, seorang petugas gudang tiba membawa daftar baru dan melarang siapa pun membuka karung tanpa izin tertulis dari Bagas.'] },
      { chapterNumber: 34, title: 'Tangga Gudang Dirantai', paragraphs: ['Rantai baru melilit tangga rak atas dan terkunci pada tiang penyangga. Bagas menyebut ada laporan pencurian benih, walau daftar isi rak tidak berkurang sebutir pun. Vina berjalan ke tetangga untuk meminjam tangga bambu; dua kru sudah berdiri di depan pintu gudang ketika ia kembali. Karsa hanya bisa mengendus debu di kertas dan menyarankan penjualan rak atas dihentikan.'] },
      { chapterNumber: 35, title: 'Pesanan Tetap Ditagih', paragraphs: ['Surat kantor memerintahkan Vina memenuhi pesanan dari rak atas atau membayar denda pembatalan. Ia menolak mengirim benih yang belum dibelah dan diperiksa. Petang itu tiga penanam berdiri di terasnya menagih uang muka. Vina membuka kaleng kas lumbung dan mengembalikan semuanya, sehingga yang tersisa hanya cukup menyalakan tungku pengering selama dua hari.'] },
      { chapterNumber: 36, title: 'Tungku Kehabisan Kayu', paragraphs: ['Uang di kaleng tidak menutup harga kayu bakar, sehingga Vina memasukkan ranting basah ke tungku. Asap tebal turun dan mengendap di lumbung bawah. Bagas datang mengukur kelembapan dinding, menuliskan angkanya, dan mengancam mencabut izin simpan bila angka itu belum turun Senin. Karsa menawarkan membayar kayu asalkan malam ini juga ia boleh mengambil contoh benih.'] },
      { chapterNumber: 37, title: 'Contoh Benih Dirampas', paragraphs: ['Karsa memanjat lewat jendela belakang dan menggenggam segenggam butir dari rak atas. Ia tertangkap ketika turun; kantong contohnya direbut dan disobek di depan pintu. Bagas menahan gerobak dagang pedagang itu sebagai barang pemeriksaan. Vina diberi dua pilihan: menandatangani laporan pencurian atas nama Karsa, atau menanggung denda kelembapan seorang diri sebelum Senin.'] },
      { chapterNumber: 38, title: 'Gerobak Karsa Ditahan', paragraphs: ['Vina menolak membubuhkan nama pada laporan itu, sehingga gerobak Karsa tetap terkunci di halaman kantor. Pedagang itu kehilangan pasar bawah dan mengembalikan uang muka empat pembeli dari kantongnya. Untuk menebus kayu bakar, Vina menjual dua tampah benih sehat kepada penanam seberang. Persediaan musim depan berkurang sebelum asal debu hitam itu diketahui siapa pun.'] },
      { chapterNumber: 39, title: 'Rak Bawah Ikut Diperiksa', paragraphs: ['Petugas melebarkan pemeriksaan ke rak bawah dengan alasan asap dapat menyebarkan jamur. Mereka memberi tempo sehari untuk memindahkan benih sehat, tetapi melarang satu karung pun keluar dari halaman. Vina menumpuknya di teras bambu, lalu menghitung kain penutup: hanya cukup menyelimuti separuh tumpukan. Awan tebal sudah menggantung di puncak sejak sore.'] },
      { chapterNumber: 40, title: 'Teras Kehujanan Malam', paragraphs: ['Hujan turun lebih awal dan membasahi sudut enam karung di teras. Vina dan Danu memikulnya ke arah tungku, tetapi petugas menutup pintu lumbung sebab jam kerja gudang telah lewat. Mereka berjaga di bawah payung anyaman sampai pagi, bergantian memutar karung agar sisi basahnya menghadap angin. Bagas menawarkan membuka pintu asalkan catatan debu hitam dicoret lebih dulu.'] },
      { chapterNumber: 41, title: 'Karung Atas Berbau Asam', paragraphs: ['Vina menemukan tujuh karung di rak atas berbau asam dan berdebu hitam pada bagian jahitannya. Karsa mengenali tanda itu sebagai benih yang pernah disimpan terlalu lembap, tetapi tidak tahu siapa yang membawanya masuk. Vina menandai setiap karung dengan tali merah. Saat ia turun dari tangga, Bagas menghadang dekat kusen gudang dan meminta semua karung itu tetap berada di tempatnya.'] },
      { chapterNumber: 42, title: 'Tali Merah Dipotong', paragraphs: ['Malamnya petugas memutus setiap simpul tali merah dan mendorong tujuh karung itu bercampur ke tumpukan lain. Vina mengenali jahitan hitam pada mulut karung, lalu menggambar tanda arang di lantai tepat di bawah masing-masing. Sebuah pesan menyusul dari kantor: ia harus menghadap besok pagi, dan bila tidak, izin lumbung dibekukan sebelum penanam datang mengambil pesanan.'] },
      { chapterNumber: 43, title: 'Pemeriksa Datang Tanpa Pemberitahuan', paragraphs: ['Pagi berikutnya dua petugas kecamatan datang membawa surat pemeriksaan setelah menerima laporan tanpa nama. Mereka menyegel pintu lumbung dan melarang satu butir pun keluar sampai penghitungan selesai. Penanam yang sudah membayar muka berkumpul di halaman sambil meminta benih mereka. Vina tidak dapat membuka apa pun, sementara Bagas menyebut segel itu akibat kecerobohannya menjaga gudang.'] },
      { chapterNumber: 44, title: 'Uang Muka Dikembalikan', paragraphs: ['Dua belas penanam berdiri di depan pintu tersegel dan menuntut uang mereka kembali. Vina membongkar tabungan untuk enam orang dan menulis surat utang bagi sisanya di atas lutut. Bagas menjanjikan segel dicabut asalkan ia menyatakan debu itu berasal dari asap tungkunya. Karsa membuka buku dagang dan menunjukkan kuitansi: tujuh karung tiba sebelum tungku menyala musim ini.'] },
      { chapterNumber: 45, title: 'Kuitansi Karsa Dibakar', paragraphs: ['Petugas merampas kuitansi itu di gerbang dan melemparnya ke tungku kantor sampai menghitam. Karsa masih menghafal nomor pengiriman yang tersalin di buku dagangnya, tetapi gerobaknya diumumkan akan dilelang esok untuk menutup denda pasar yang terlewat. Penghitungan karung dijadwalkan pada jam yang persis sama, dan Vina hanya bisa berada di satu tempat.'] },
      { chapterNumber: 46, title: 'Daun Semai Disita', paragraphs: ['Ketika pemeriksa menemukan catatan kapur pada tujuh karung, mereka mengambil seluruh contoh benih dan memerintahkan kebun percobaan ditutup. Karsa kehilangan tempat menjual bibit selama penyelidikan, sedangkan Vina diminta hadir setiap pagi untuk menjawab pertanyaan. Bagas menawarkan membatalkan laporan bila tanda merah dicabut dari karung. Vina menolak, lalu melihat petugas menggembok tungku pengering yang dipakai warga bersama.'] },
      { chapterNumber: 47, title: 'Gerobak Dilelang Murah', paragraphs: ['Vina memilih halaman lelang dan tiba ketika gerobak sudah berpindah kepada kerabat petugas dengan harga sepertiga. Karsa berjalan kaki menuruni jalan sambil mendekap buku dagang. Di kantor kecamatan penjaga meminta surat pengantar dari Bagas sebelum mau menerima salinan nomor kiriman. Gembok tungku bersama belum dibuka, sementara benih sehat menyerap lembap dari udara berkabut.'] },
      { chapterNumber: 48, title: 'Lumbung Bawah Disegel', paragraphs: ['Bercak jamur putih tumbuh pada dua karung sehat karena tungku tidak bisa dinyalakan. Pemeriksa menempelkan segel kedua di lantai bawah dan memerintahkan seluruh pembeli mengajukan pengembalian dana dalam tiga hari. Uang di kaleng Vina tinggal seperempatnya. Bagas mengirim tawaran pinjaman kantor dengan satu syarat tertulis: lumbung diserahkan sebagai jaminan sampai lunas.'] },
      { chapterNumber: 49, title: 'Lumbung Menjadi Jaminan', paragraphs: ['Vina merobek surat pinjaman itu di depan pengantarnya, lalu membagikan benih sehat yang tersisa kepada para pembeli tanpa menunggu izin. Petugas berdiri di gerbang mencatat nama setiap penerima, kemudian memaku surat sita pada kusen. Karsa menyelipkan buku dagangnya ke tangan Bu Ningsih sesaat sebelum dua kru membawanya pergi untuk diperiksa karena membantu pembagian.'] },
      { chapterNumber: 50, title: 'Nomor Kiriman Dibacakan', paragraphs: ['Di halaman sekolah, Bu Ningsih membacakan nomor kiriman itu keras-keras kepada para penanam yang berdiri di rumput basah. Nomor tersebut menunjuk gudang milik kantor Bagas. Pemeriksa kecamatan menyalinnya, namun surat sita di kusen lumbung belum dicabut. Vina tidur di teras beralas karung kosong; Karsa masih ditahan dan gerobaknya sudah berganti pemilik.'] },
    ], justification: 'Bab 33–50 turns suspicious dust into blocked access, forced orders, refunds, confiscated samples, a sealed warehouse, a locked shared dryer, buyer claims, and seizure. Karsa loses his cart and freedom while Vina gives away stock and risks the warehouse to expose the shipment number.' },
    { chapters: [
      { chapterNumber: 33, title: 'Daftar Pemetik Diganti', paragraphs: ['Danu menemukan namanya berpindah ke regu paling jauh tanpa pemberitahuan lebih dulu. Ia harus berangkat sebelum subuh agar tidak kehilangan hitungan pertama. Vina menanyakannya kepada kepala kebun, yang membalikkan papan daftar dan menunjuk cap Bagas di sudut bawah. Perubahan itu mulai berlaku esok, sedangkan lampu minyak jalan depan rumah mereka masih pecah kacanya.'] },
      { chapterNumber: 34, title: 'Subuh Tanpa Lampu', paragraphs: ['Danu berangkat dalam gelap dengan obor pendek yang padam dua kali. Pada tikungan teras ia terpeleset, dan bekalnya tumpah ke parit. Ia sampai setelah hitungan pertama ditutup, sehingga upah hari itu dipotong seperempat. Kepala regu menyodorkan surat kecil: keterlambatan berikutnya membuat kartu jatah air rumahnya diperiksa oleh kantor pengairan.'] },
      { chapterNumber: 35, title: 'Jalan Kebun Ditutup', paragraphs: ['Kru memasang pagar bambu melintang di jalan pendek sehingga para pemetik harus memutar lewat lereng basah. Danu berangkat lebih awal, tetapi longsoran setinggi lutut menahan regunya di tengah jalur. Vina turun membawa surat saksi bertanda tangan Mbah Ripto. Kepala kebun mendorong surat itu kembali karena penulisnya bukan pegawai kebun.'] },
      { chapterNumber: 36, title: 'Potongan Upah Kedua', paragraphs: ['Jalan memutar memakan waktu lagi dan seperempat upah Danu kembali hilang. Uang di dapur tidak cukup untuk beras dan minyak sekaligus. Vina menukar dua bungkus benih sayur dengan sebotol minyak kepada tetangga seberang. Malamnya Bagas mengirim tawaran: jalan pendek dibuka bila Danu menandatangani aturan baru yang mengikat kehadiran kerja dengan jatah air keluarga.'] },
      { chapterNumber: 37, title: 'Aturan Dibawa Pulang', paragraphs: ['Danu membawa lembar aturan itu pulang dengan lipatan masih rapi. Tenggatnya Jumat pagi; setelah itu namanya dicoret dari regu dekat. Vina membaca satu pasal dengan jari menelusuri barisnya: kantor boleh menghentikan air selama sengketa kerja berlangsung. Mereka mendatangi pemetik lain untuk mengajukan keberatan bersama, namun setiap orang ternyata menerima lembar dengan isi berlainan.'] },
      { chapterNumber: 38, title: 'Lembar Berbeda Dikumpulkan', paragraphs: ['Empat versi kontrak berjajar di meja rumah Bu Ningsih, masing-masing memuat hukuman sendiri: air, benih, tempat tinggal, atau upah. Seorang kru berdiri lama di jendela sekolah sambil pura-pura mengikat sandal. Keesokan harinya dua pemetik yang menyerahkan salinan kepada Vina dipindah ke regu malam dan kehilangan uang makan.'] },
      { chapterNumber: 39, title: 'Regu Malam Bertambah', paragraphs: ['Delapan pemetik yang menolak membubuhkan nama dipindahkan ke giliran malam, Danu di antaranya. Barak hanya berisi empat tikar dan satu tungku kecil. Vina mendaki membawa selimut, tetapi penjaga menahannya di gerbang karena keluarga dilarang masuk setelah lonceng petang. Ia menggantungkan bungkusan itu pada pagar ketika hujan mulai turun.'] },
      { chapterNumber: 40, title: 'Selimut Disita Penjaga', paragraphs: ['Selimut itu Vina temukan pagi berikutnya di kantor, terlipat dengan label barang terlarang tersemat. Danu pulang menggigil dan langsung diperintahkan kembali sebelum sore atau seluruh upah tiga harinya hangus. Menjelang siang seorang kru mengantar kontrak baru ke rumah mereka, kali ini dengan kolom tanda tangan saksi keluarga di samping cap kantor.'] },
      { chapterNumber: 41, title: 'Surat Kontrak Danu', paragraphs: ['Danu menerima surat kontrak baru dari kebun teh: pemetik yang terlambat satu hari akan kehilangan jatah air rumahnya. Ia menyembunyikan surat itu di bawah tikar, namun Vina menemukannya saat mencari jarum. Di pojok kertas terdapat cap kantor Bagas. Vina meminta kakaknya menolak menandatangani, tetapi Danu berkata keluarga mereka tidak punya pekerjaan pengganti.'] },
      { chapterNumber: 42, title: 'Tanda Tangan Dipaksa', paragraphs: ['Kepala regu menyimpan keranjang Danu di gudang alat sampai kontrak itu ditandatangani, dan tanpa keranjang daun petikannya tidak dihitung. Vina mendaki membawa keranjang rotan milik rumah, tetapi penjaga merampasnya di gerbang karena tidak bernomor kebun. Menjelang tengah hari Danu membubuhkan namanya di kolom bawah supaya kerja sehari itu tidak hilang seluruhnya.'] },
      { chapterNumber: 43, title: 'Pemetik Tidak Boleh Pulang', paragraphs: ['Hujan besar membuat jalan kebun longsor dan para pemetik ditahan di barak sampai daun teh selesai dipilah. Danu tidak pulang dua malam. Vina membawa makanan ke gerbang, tetapi penjaga mengatakan nama keluarga yang protes akan dicoret dari daftar musim depan. Ia pulang membawa rantang penuh dan mendapati kartu jatah air rumah mereka sudah diberi tanda silang biru.'] },
      { chapterNumber: 44, title: 'Air Rumah Berhenti', paragraphs: ['Petugas menutup aliran ke halaman mereka sebelum fajar, mengikuti tanda silang biru itu. Vina mengantre di pancuran umum sejak gelap, namun kru mendahulukan keluarga pemetik yang menandatangani tanpa membantah. Rantang untuk Danu masih kosong ketika matahari sudah tinggi. Bagas lewat dan menjanjikan satu tempayan penuh asalkan Vina berhenti mendatangi gerbang barak.'] },
      { chapterNumber: 45, title: 'Rantang Dilempar Pagar', paragraphs: ['Vina mengisi rantang di dapur Bu Ningsih, lalu melemparkannya melewati pagar barak. Penjaga menginjak tutupnya sampai nasi tumpah ke lumpur dan menuliskan nama guru itu di buku jaga. Sore harinya sekolah menerima surat bahwa jatah airnya ditunda besok. Ningsih melipat surat tersebut dan berkata ia akan membacakan kontrak di barak sebelum penundaan berlaku.'] },
      { chapterNumber: 46, title: 'Nama Keluarga Dicoret', paragraphs: ['Vina mendatangi barak bersama Bu Ningsih dan membacakan isi kontrak di depan para pemetik. Bagas langsung mencoret nama Danu dari daftar kerja, lalu memerintahkan rumah Vina menerima air paling akhir sampai akhir musim. Danu pulang tanpa upah untuk tiga hari kerja. Di dapur, ia berkata mungkin lebih baik Vina diam saja; dari luar terdengar saluran mengering sebelum mencapai halaman mereka.'] },
      { chapterNumber: 47, title: 'Rumah Terakhir Menerima', paragraphs: ['Aliran tiba di halaman mereka setipis benang, jauh setelah rumah-rumah lain selesai mengisi. Vina hanya sanggup menampung setengah kendi sebelum air berhenti sama sekali. Danu menawarkan tenaga memotong bambu di kebun seberang, tetapi pemiliknya membuka surat larangan mempekerjakan orang yang dicoret dari daftar. Botol obat batuk Danu sudah kosong dan upah baru belum ada.'] },
      { chapterNumber: 48, title: 'Pemetik Menghentikan Keranjang', paragraphs: ['Empat pemetik meletakkan keranjang mereka di tanah dan menolak naik ke petak sebagai dukungan bagi Danu. Kepala regu mengunci keempatnya di barak dan menahan upah sepekan. Bagas berteriak dari jalan bahwa mereka punya waktu sampai petang untuk kembali bekerja. Vina turun ke pasar membawa salinan kontrak; keluarga pemetik sudah berkumpul di sana dengan kartu bersilang biru.'] },
      { chapterNumber: 49, title: 'Kartu Bersilang Dibakar', paragraphs: ['Petugas menyapu kartu-kartu itu dari meja pasar dan melemparkannya ke tungku pengering teh. Beberapa keluarga mengejar sampai halaman kantor, lalu kru memutar tuas dan menutup pancuran umum. Vina menyelipkan satu lembar kontrak ke balik bajunya. Danu berkata lembar itu sebaiknya diserahkan agar air dibuka, tetapi para pemetik memilih berjalan bersama ke kantor kecamatan.'] },
      { chapterNumber: 50, title: 'Keranjang Kosong Diarak', paragraphs: ['Rombongan menuruni jalan kecamatan sambil memanggul keranjang kosong dan satu lembar kontrak yang selamat. Petak teh tidak dipetik seharian. Kepala dusun menyusul, dan petugas membuka pancuran umum sore itu, meski giliran rumah Vina tetap yang paling akhir sampai musim habis. Danu berjalan di barisan depan memegang lembar bercap Bagas; ia masih tanpa pekerjaan.'] },
    ], justification: 'Bab 33–50 escalates from distant shifts and wage deductions to coerced contracts, barred families, water sanctions, withheld pay, blacklisting, and a closed public fountain. Danu loses three days’ wages and his job while Vina exposes the contract despite their household remaining last in line.' },
    { chapters: [
      { chapterNumber: 33, title: 'Garis Kapur Bergeser', paragraphs: ['Garis kapur pada jam air kantor sudah bergeser satu ruas ketika giliran warga selesai, dan Vina menyaksikannya dari balik pagar. Mbah Ripto mengeluarkan jam pasir tuanya sebagai pembanding, lalu mereka menuliskan selisihnya pada sehelai daun bambu memakai ujung arang. Tiga kru datang menghalau warga dan melarang siapa pun berdiri dekat alat kantor tanpa surat tugas.'] },
      { chapterNumber: 34, title: 'Daun Catatan Disobek', paragraphs: ['Seorang petugas merogoh saku Ripto, menemukan daun bambu bercatatan itu, dan menyobeknya menjadi serpih. Orang tua itu masih menyimpan angkanya di kepala, tetapi kru memaku jendela rumah jaga agar wajah jam kantor tak terlihat dari luar. Vina melubangi anyaman dinding seukuran biji jagung. Bila kedapatan sekali lagi, kartu jatah air petaknya ditahan sepekan.'] },
      { chapterNumber: 35, title: 'Anyaman Ditutup Seng', paragraphs: ['Selembar seng sudah terpaku menutup anyaman itu sebelum Vina kembali. Bunyi tetes jam masih terdengar, namun angkanya hilang di balik logam. Ripto mencoba menghitung dengan denyut nadi di pergelangannya, dan kru tertawa mendengar hasilnya. Bagas menetapkan syarat baru: keberatan berikutnya harus disertai alat ukur bercap kantor, diserahkan sebelum Jumat.'] },
      { chapterNumber: 36, title: 'Pasir Pembanding Dicari', paragraphs: ['Toko di pasar hanya menjual pasir kering dalam kantong besar, jauh lebih banyak daripada kebutuhan jam tua itu. Vina menukarnya dengan dua ikat daun petikan. Di teras, Ripto menakar butiran halus ke dalam botol kecil dengan corong kertas. Saat mereka pulang, petugas membuka bungkusan itu di jalan dan menumpahkan separuh pasir ke lumpur sebagai bahan tanpa izin.'] },
      { chapterNumber: 37, title: 'Botol Waktu Disembunyikan', paragraphs: ['Ripto memasukkan sisa pasir ke botol dan menyelipkannya ke rongga bawah meja rumah jaga. Malam itu Vina membandingkan satu giliran: kantor menutup air tujuh belas menit lebih awal. Kru mengetuk keras sebelum ia selesai menulis, lalu merampas pensil dan buku hitungannya dari tangan. Botol tetap tersembunyi di kolong, tertutup papan lantai yang basah.'] },
      { chapterNumber: 38, title: 'Lantai Rumah Dibongkar', paragraphs: ['Atas perintah Bagas, papan lantai rumah jaga dicungkil satu per satu untuk mencari alat ukur tak berizin. Botol pasir itu terangkat dan dibawa ke kantor dalam kain lap. Ripto terpaksa tidur di rumah Vina sebab lantainya menganga sampai ke tanah. Petugas memberinya tiga hari: terima jam kantor, atau hak tinggal di rumah jaga dicabut.'] },
      { chapterNumber: 39, title: 'Hak Tinggal Dicabut', paragraphs: ['Ripto menolak menempelkan cap jempol pada surat penerimaan, sehingga barangnya dikeluarkan ke pinggir jalan pada hari ketiga. Vina memikul tikar dan ketel tembaga orang tua itu ke lumbungnya. Bagas menunjuk seorang kru muda sebagai penjaga baru. Mulai esok Ripto dilarang mendekati saluran yang dirawatnya puluhan tahun tanpa didampingi petugas.'] },
      { chapterNumber: 40, title: 'Meja Tua Ditendang', paragraphs: ['Ripto kembali untuk mengambil meja tuanya sebelum rumah jaga dikunci. Seorang kru menendang kaki meja sampai sisa pasir dalam tabung berdesir ke satu sisi. Vina menahan papan atasnya dengan kedua tangan, lalu dua penjaga menyeretnya sampai ke jalan. Bagas berdiri di sana memegang selembar pengumuman: hanya alat kantor yang berlaku mulai hari itu.'] },
      { chapterNumber: 41, title: 'Jam Pasir Pecah', paragraphs: ['Jam pasir tua milik Mbah Ripto pecah ketika kru saluran menendang meja rumah jaga saat memeriksa giliran. Pasirnya bercampur lumpur dan tidak bisa dipakai mengukur aliran. Bagas lalu mengumumkan bahwa hanya jam kantor yang berlaku. Vina melihat petugas memutar jam itu jauh dari pandangan warga. Tanpa alat pembanding, setiap protes dapat disebut salah hitung.'] },
      { chapterNumber: 42, title: 'Lonceng Fajar Dimajukan', paragraphs: ['Penjaga baru memukul lonceng jauh sebelum ayam berkokok, lalu memutar tuas ke arah petak Bagas. Vina berjongkok di pematang menghitung panjang bayang rumpun bambu pada tanah. Ripto menyebut selisihnya hampir setengah jam. Jejak basah di tanah itu satu-satunya bukti yang tersisa, dan hujan biasanya turun sesudah tengah hari.'] },
      { chapterNumber: 43, title: 'Air Lewat Saat Fajar', paragraphs: ['Vina bangun sebelum fajar untuk mengamati gerbang dari balik rumpun bambu. Air menuju petak Bagas dibuka dua puluh menit lebih awal, lalu ditutup saat ayam berkokok. Ketika ia mencoba mendekat, kru mengejar dan merampas catatan waktunya. Ia sempat menyebutkan angka itu kepada Bu Ningsih, tetapi kertasnya sudah dibawa ke kantor bersama sandal yang tertinggal di lumpur.'] },
      { chapterNumber: 44, title: 'Sandal Dipajang Kantor', paragraphs: ['Sandal itu tergantung pada palang gerbang bersama tulisan arang “pengganggu saluran”. Petugas menjanjikan pengembaliannya bila Bu Ningsih mencabut kesaksiannya. Vina memilih menemui guru itu dan menempuh jalan berbatu tanpa alas kaki. Telapaknya robek pada batu bersudut menjelang sekolah, dan pagi berikutnya habis untuk membalut luka, bukan menanam.'] },
      { chapterNumber: 45, title: 'Kesaksian Dibaca Sekolah', paragraphs: ['Bu Ningsih menulis angka dua puluh menit di papan kelas dan membacakannya kepada para orang tua murid yang berdiri di pintu. Kru tiba menutup halaman sekolah, tetapi belasan orang telanjur menyalin angka itu ke bungkus rokok dan telapak tangan. Sore harinya Bagas mengirim dua pekerja bergergaji ke jalan bambu, satu-satunya jalur pendek bagi Ripto yang kakinya sakit.'] },
      { chapterNumber: 46, title: 'Jalan Bambu Dipotong', paragraphs: ['Bu Ningsih membacakan waktu yang diingat Vina di depan warga sekolah. Sore itu jalan bambu menuju rumah jaga dipotong dan dijatuhkan ke jurang, memaksa semua orang memutar dua jam lewat kebun teh. Bagas berkata jembatan rusak karena hujan. Vina membawa Mbah Ripto yang kakinya sakit melalui jalan memutar, lalu memilih melepas satu kesempatan menanam agar orang tua itu tiba sebelum gelap.'] },
      { chapterNumber: 47, title: 'Jalan Putar Dijaga', paragraphs: ['Dua kru berdiri di ujung jalur memutar dan membongkar setiap bawaan yang lewat. Mereka menyita batang arang tulis pemberian Ningsih dari kantong Vina. Ripto kehabisan napas pada tanjakan terakhir dan duduk di batu. Vina memanggulnya sampai puncak, sementara di lereng seberang giliran petaknya lewat tanpa seorang pun membuka pintu air.'] },
      { chapterNumber: 48, title: 'Rumah Jaga Dirobohkan', paragraphs: ['Bagas memerintahkan rumah jaga dirobohkan dengan alasan tanahnya rawan longsor. Peti-peti arsip giliran lama dinaikkan ke gerobak dan didorong menuju kantor. Vina dan Ripto berdiri menghalangi roda, lalu kru menawarkan pilihan: menyingkir sebelum siang, atau seluruh kartu warga yang berkumpul ditahan. Orang-orang mundur ke tepi sambil menyalin nomor pada bak gerobak.'] },
      { chapterNumber: 49, title: 'Gerobak Arsip Dikejar', paragraphs: ['Vina menerobos kebun teh dan memotong jalan gerobak itu dekat tungku pengering. Petugas melempar dua peti arsip ke selokan supaya bebannya ringan dan roda dapat lolos. Ripto meraih satu buku dari air sambil terjatuh menelungkup, dan kru menyeretnya berdiri untuk dibawa. Vina memeluk buku basah itu dan mendaki ke sekolah lewat lereng berlumpur.'] },
      { chapterNumber: 50, title: 'Waktu Lama Dibandingkan', paragraphs: ['Ningsih menjajarkan buku basah itu dengan jadwal kantor di hadapan warga yang memenuhi ruang kelas. Barisan angkanya memperlihatkan potongan serupa berulang selama enam pekan. Kepala dusun turun tangan dan Ripto dilepaskan sore itu, tetapi rumah jaganya sudah rata dan jalan bambu masih tergeletak di dasar jurang. Vina menyimpan buku itu di lumbung menunggu pemeriksa kecamatan.'] },
    ], justification: 'Bab 33–50 removes every independent way to time water: notes are torn, views blocked, measuring sand seized, Ripto evicted, and his clock broken. Observation costs Vina her notes and sandal, public testimony triggers a cut bridge, and saving old records requires chasing a guarded cart.' },
    { chapters: [
      { chapterNumber: 33, title: 'Nomor Petak Bertumpuk', paragraphs: ['Pada daftar jatah, dua nomor petak tertulis bertindih di baris yang sama. Angka bawah milik kebun lereng Vina; angka atas ditulis belakangan dengan tinta lebih tebal. Petugas mengetukkan jari pada angka atas dan menyuruhnya memakai itu saja. Vina menyalin keduanya ke punggung nota sebelum daftar tersebut digulung dan dibawa ke kantor Bagas.'] },
      { chapterNumber: 34, title: 'Salinan Ditolak Kepala', paragraphs: ['Kepala dusun enggan membubuhkan cap pada salinan itu selama daftar aslinya belum ia lihat sendiri. Vina menelusuri pemilik nomor atas sampai ke sebuah rumah kosong yang ditinggalkan keluarganya musim lalu. Tetangga sebelah berkata kartu mereka sudah dibeli seorang kru. Malamnya pintu petak Vina hanya dibuka separuh dari giliran biasa.'] },
      { chapterNumber: 35, title: 'Setengah Giliran Hilang', paragraphs: ['Tanah di ujung petak belum sempat basah ketika kru memutar tuas menutup pintu. Vina menyodorkan salinan angka ganda itu, tetapi petugas menyatakan separuh airnya sudah diserahkan kepada pemegang kartu lain. Ia harus menghadirkan orang tersebut sebelum Kamis; jika tidak, pembagian yang baru berlaku tetap sampai akhir bulan.'] },
      { chapterNumber: 36, title: 'Rumah Kosong Disegel', paragraphs: ['Vina dan Bu Ningsih mendaki ke rumah kosong itu dan menemukan segel kantor sudah menempel pada daun pintunya. Lewat celah jendela terlihat setumpuk kartu biru tergeletak di meja. Kru datang menuduh mereka hendak mencuri isi rumah. Bagas menawarkan dua jalan: pulang tanpa mencatat apa pun, atau kartu Vina ditahan selama penyelidikan.'] },
      { chapterNumber: 37, title: 'Kartu Vina Ditahan', paragraphs: ['Vina menghafal deretan nomor di meja itu lewat celah jendela dan menolak beranjak sebelum kartu-kartu dihitung di depan saksi. Petugas mencabut kartunya sendiri dari saku baju. Tanpa kartu, aliran berikutnya tidak akan sampai ke petaknya. Bu Ningsih menuliskan nomor yang disebutkan Vina, lalu menyelipkan kertas itu ke sampul buku pelajaran sebelum tas mereka digeledah.'] },
      { chapterNumber: 38, title: 'Sekolah Kehilangan Jatah', paragraphs: ['Kabar bahwa Ningsih menyimpan nomor sampai ke kantor, dan jatah air sekolah dipotong satu tempayan pada hari itu juga. Para murid datang membawa botol dari rumah masing-masing. Vina membuka tempayan air hujan lumbungnya untuk sekolah, cukup untuk dua hari. Bagas menetapkan pilihan: catatan diserahkan, atau tungku dapur sekolah berhenti Jumat.'] },
      { chapterNumber: 39, title: 'Dapur Sekolah Padam', paragraphs: ['Jumat tiba dan kertas itu tetap di sampul buku, sehingga dapur sekolah tidak menanak bubur. Murid-murid pulang menjinjing mangkuk kosong sampai ke pematang. Beberapa orang tua mendesak Ningsih menyerahkan salinan sore itu juga. Vina meminta tempo satu hari, lalu menuruni jalan setapak ke dusun bawah tempat keluarga pemilik kartu itu dahulu tinggal.'] },
      { chapterNumber: 40, title: 'Janda Membawa Kartu', paragraphs: ['Di dapur berlantai tanah dusun bawah, seorang janda mengeluarkan kartu mendiang suaminya dengan nomor yang sama persis. Ia bercerita bahwa Bagas menjanjikan tambahan air asalkan kartu itu disimpan dan tidak diperlihatkan. Vina mengajaknya ke balai esok pagi. Malamnya dua kru berjaga di mulut jalan keluar, menusuk setiap keranjang yang dibawa warga.'] },
      { chapterNumber: 41, title: 'Kartu Biru Berpindah Tangan', paragraphs: ['Seorang ibu dari dusun bawah datang membawa kartu jatah biru atas nama suaminya yang sudah meninggal. Nomor petaknya ternyata sama dengan satu petak di lereng Vina. Vina melihat cap baru menutupi tulisan lama dan meminta kartu itu ditinggal semalam. Ibu tersebut takut, sebab Bagas menjanjikan air tambahan jika ia tidak memperlihatkannya kepada siapa pun.'] },
      { chapterNumber: 42, title: 'Jalan Dusun Diperiksa', paragraphs: ['Vina menanam kartu biru itu di dasar keranjang daun petikan dan menaikinya jalan ke balai. Kru menghentikannya di jembatan, menusuk-nusuk tumpukan daun dengan ujung bambu runcing, lalu melepasnya lewat. Di belakang, janda itu ditahan di halaman rumahnya dan diancam kehilangan jatah minum bila tidak menyebutkan tempat kartu disembunyikan.'] },
      { chapterNumber: 43, title: 'Petak Bawah Kehilangan Aliran', paragraphs: ['Saat Vina menyalin nomor kartu itu, pintu saluran ke dusun bawah ditutup pada tengah hari. Dua puluh rumah kehilangan air minum dan mulai mengambil dari sumur yang keruh. Bagas mendatangi ibu pemilik kartu, menuduhnya menjual jatah, lalu menyuruhnya memilih antara menyerahkan kartu kepada kantor atau melihat nama anaknya dicoret dari sekolah bantuan.'] },
      { chapterNumber: 44, title: 'Sumur Keruh Menyakitkan', paragraphs: ['Tiga anak muntah semalaman setelah minum dari sumur yang airnya cokelat. Ningsih membuka ruang kelas sebagai tempat merebus air dan membakar kayu cadangan sekolah sampai habis separuh. Bagas mengirim pesan bahwa saluran dibuka bila kartu asli dikembalikan sebelum malam. Janda itu memegang lengan Vina dan memintanya menyimpan salinan saja agar nama anaknya tetap tercantum pada bantuan.'] },
      { chapterNumber: 45, title: 'Kartu Asli Diserahkan', paragraphs: ['Vina menjiplak cap dan deretan nomornya pada kertas tipis, kemudian janda itu mengantar kartu asli ke kantor. Saluran dibuka satu jam lalu ditutup lagi sebab salinan disebut masih beredar di dusun. Bagas menetapkan batas sampai rapat malam untuk menyerahkan jiplakan tersebut. Jika lewat, sumur umum akan ditutup dengan alasan pencemaran.'] },
      { chapterNumber: 46, title: 'Warga Membawa Ember Kosong', paragraphs: ['Vina menyerahkan salinan nomor ganda kepada kepala dusun pada rapat malam. Bagas membalas dengan menutup sumur umum menggunakan rantai dan gembok, katanya untuk mencegah pencurian air. Warga datang ke lumbung Vina membawa ember kosong, termasuk ibu pemilik kartu yang kini tidak berani pulang. Vina membongkar simpanan air hujan untuk mereka, walau itu berarti benih di lantai bawah terkena tampias.'] },
      { chapterNumber: 47, title: 'Lantai Benih Kebanjiran', paragraphs: ['Air yang dituang ke ember warga tumpah di depan pintu dan merembes turun ke lantai simpanan. Lima karung benih menyerap basah sampai ke jahitannya. Vina menggeser semuanya ke dekat tungku, sementara antrean masih memanjang sampai teras. Menjelang malam datang pesan dari kantor: rantai sumur dibuka setelah setiap salinan dibakar di hadapan Bagas.'] },
      { chapterNumber: 48, title: 'Rantai Sumur Dipotong', paragraphs: ['Warga menolak menyalakan api untuk salinan itu dan memutus rantai sumur dengan mata kapak. Kru berdatangan merampas kapak serta menggiring kepala dusun ke kantor. Vina membacakan nomor ganda itu berulang kepada setiap orang di antrean sampai petugas menyita kertasnya. Sumur kembali terbuka, namun jalan ke saluran dijaga dan kartu warga dikumpulkan satu per satu.'] },
      { chapterNumber: 49, title: 'Kartu Warga Ditumpuk', paragraphs: ['Ratusan kartu biru bertumpuk di meja kantor untuk diperiksa ulang, dan warga mengantre sampai ke jalan. Bagas memberi tempo sehari bagi siapa pun yang mau mengaku pernah meminjamkan kartunya. Janda itu berdiri di samping Vina dan menyebutkan janji air tambahan itu keras-keras di depan antrean. Petugas mencoret nama anaknya dari daftar bantuan sekolah pada saat itu juga.'] },
      { chapterNumber: 50, title: 'Nomor Ganda Dicatat', paragraphs: ['Ningsih mengirim seorang murid lewat jalan kebun, dan pemeriksa kecamatan tiba keesokan siang. Ia menyalin nomor ganda itu ke berkasnya, lalu menyegel meja kartu. Saluran dusun bawah mengalir lagi menjelang senja. Bantuan sekolah anak janda itu belum dipulihkan, lima karung Vina dibuang ke jurang, dan kepala dusun masih ditahan karena memotong rantai.'] },
    ], justification: 'Bab 33–50 turns a duplicate number into halved irrigation, a withheld card, a school ration cut, twenty dry households, sick children, a locked well, wet seed losses, mass card collection, and retaliation against the widow’s child. Delay repeatedly transfers harm to the village.' },
  ],
  WEAK: [
    { chapters: [
      { chapterNumber: 33, title: 'Kabut Turun Perlahan', paragraphs: ['Kabut turun dari puncak sampai ujung teras hilang dari pandangan. Vina menggulung tikar jemuran sambil memikirkan kantor pengairan, lalu membawanya masuk. Ia menyalakan tungku, memanaskan air, dan mengiris singkong untuk santapan malam. Danu pulang membawa keranjang setengah penuh serta cerita tentang jalan yang licin. Kartu jatah air tergantung pada paku dekat pintu dengan angka yang sudah lama tertulis di sana.'] },
      { chapterNumber: 34, title: 'Dingin Menempel Genting', paragraphs: ['Embun menetes dari genting sepanjang pagi. Sambil menyapu lantai, Vina membayangkan Bagas sedang menyusun jadwal di mejanya. Mbah Ripto lewat memanggul dua batang bambu, berhenti sebentar, dan berbicara tentang hujan di lereng atas. Vina membuka lumbung pada jam yang sama seperti kemarin, menimbang dua kilogram benih untuk seorang pembeli, kemudian menutup daun pintunya kembali.'] },
      { chapterNumber: 35, title: 'Selendang Dijemur Pagi', paragraphs: ['Matahari muncul cukup lama untuk menjemur selendang yang lembap. Angin lembah membawa pikiran Vina kembali kepada pembagian air. Ia menurunkan kartu dari paku, membaca angkanya, lalu menggantungnya lagi pada tempat semula. Danu tiba membawa bakul petikan dan menuangnya ke tampah lebar. Saluran di belakang halaman mengalir setinggi mata kaki sepanjang siang.'] },
      { chapterNumber: 36, title: 'Bambu Berderak Malam', paragraphs: ['Rumpun bambu berderak ketika angin malam menekannya dari arah puncak. Vina terbangun, mengira ada langkah di jalan, lalu mengintip lewat celah daun pintu. Halaman berkabut dan seekor kucing melintas di bawah lampu. Ia merapikan selimut dan kembali tidur. Pagi harinya dua helai daun pisang tersangkut di pagar, dan pintu air masih pada bukaan yang ia atur kemarin sore.'] },
      { chapterNumber: 37, title: 'Awan Menutup Lereng', paragraphs: ['Awan rendah menutupi kebun sampai jalan menuju kantor lenyap dari pandangan. Vina bertanya-tanya apakah Bagas berada di sana pagi itu. Ia mengambil sikat ijuk dan membersihkan tampah satu per satu sambil menunggu langit terbuka. Lonceng berbunyi pada waktu makan siang. Danu makan di tangga sambil bercerita tentang pemetik baru yang selalu tertinggal di ujung barisan.'] },
      { chapterNumber: 38, title: 'Ketel Mendidih Lama', paragraphs: ['Api kecil membuat ketel tua itu mendidih lambat. Vina mengingat kembali desas-desus tentang giliran air yang pernah didengarnya di pasar. Danu menuangkan teh dan berpindah bicara ke harga pupuk kandang. Mereka menghabiskan dua cangkir, mencuci gelas, lalu menutup dapur. Daftar belanja masih terselip di bawah kaleng gula, dan tampah untuk pekerjaan esok tersusun dekat tungku.'] },
      { chapterNumber: 39, title: 'Hujan Tipis Berulang', paragraphs: ['Hujan tipis turun, berhenti, lalu turun lagi di atap lumbung. Vina merasa hari itu membawa firasat yang tidak dapat ia namai. Ia menghitung karung sampai petang: enam belas pada rak atas, sembilan di bawah. Dua penanam datang membawa kartu masing-masing dan pulang dengan benih pesanan. Ia menutup rak memakai kain sebelum lampu dinyalakan.'] },
      { chapterNumber: 40, title: 'Jalan Kantor Sepi', paragraphs: ['Vina berdiri di persimpangan memandangi jalan yang menanjak ke kantor. Bayangan tentang perintah Bagas menahan langkahnya sejenak. Ia berbelok ke pasar, membeli garam serta setengah kilogram gula, lalu pulang melewati jalur yang sama. Seorang pedagang menyapanya dari balik tumpukan cabai. Di rumah ia menaruh garam pada rak dapur dan mencatat sisa uang pada lembar belanja.'] },
      { chapterNumber: 41, title: 'Angin Dingin dari Puncak', paragraphs: ['Angin dari puncak membawa kabut ke halaman lumbung dan membuat Vina menutup selendang lebih rapat. Ia memikirkan Bagas serta pembagian air yang belum jelas, lalu menyapu daun kering di depan pintu. Mbah Ripto lewat dan mengangguk tanpa berhenti. Petang tiba, lampu dinyalakan, dan kegelisahan Vina tetap berupa pikiran yang tidak bertemu orang atau tindakan apa pun.'] },
      { chapterNumber: 42, title: 'Api Dapur Mengecil', paragraphs: ['Kayu yang lembap membuat api dapur mengecil sampai nyaris padam, sehingga Vina menyusupkan segenggam ranting kering ke bawahnya. Asap menyentuh matanya dan pikirannya kembali kepada kantor pengairan. Nasi matang jauh lewat waktu makan biasa. Danu menghabiskan dua mangkuk, mencuci piringnya di tempayan, lalu pergi tidur. Kartu jatah air menggantung pada paku, sudutnya melengkung oleh uap dapur.'] },
      { chapterNumber: 43, title: 'Angin Masih Menggoyang Bambu', paragraphs: ['Dua hari kemudian bambu di belakang lumbung masih bergoyang dan kabut kembali menempel pada genting. Vina menyebut dalam hati bahwa Bagas mungkin sedang mengatur sesuatu, lalu memandangi jalan menuju kantor dari kejauhan. Tidak ada surat, penjaga, atau perubahan jadwal yang muncul. Ia memasak nasi, mencuci piring, dan menyimpan kekhawatiran yang sama sampai api dapur padam.'] },
      { chapterNumber: 44, title: 'Burung Pulang ke Sarang', paragraphs: ['Angin mereda menjelang petang dan burung-burung kembali ke rumpun bambu di belakang lumbung. Vina memasang gembok pada daun pintu sambil mengingat rasa tidak enak kemarin. Bu Ningsih menyapanya dari jalan, menyebut buku bacaan yang belum kembali dari muridnya, kemudian meneruskan langkah. Vina menjinjing keranjang kosong menuruni pematang dan tiba di rumah sebelum lampu jalan menyala.'] },
      { chapterNumber: 45, title: 'Kabut Membasahi Tikar', paragraphs: ['Kabut masuk lewat jendela yang kusennya bengkok dan membasahi ujung tikar. Vina menggeser tikar itu ke dekat tungku, membalik sisinya, lalu duduk mendengarkan angin menyapu genting. Pikirannya kembali kepada pembagian air. Di halaman belakang, aliran saluran terdengar seperti pagi tadi. Ia menambahkan dua ranting ke bara agar tikar itu kering sebelum malam benar-benar dingin.'] },
      { chapterNumber: 46, title: 'Angin Berhenti Menjelang Petang', paragraphs: ['Menjelang petang angin reda, tetapi Vina masih duduk di serambi dengan pikiran yang sama tentang pembagian air. Ia membolak-balik kartu jatah tanpa menemukan angka baru, lalu memasukkannya ke saku. Danu pulang membawa teh basah dan tidak menanyakan apa pun. Malam datang tanpa ancaman baru, keputusan baru, atau akibat yang membuat persoalan mereka menjadi lebih sempit.'] },
      { chapterNumber: 47, title: 'Pagi Terang di Teras', paragraphs: ['Pagi berikutnya langit terang sampai ke punggung bukit. Vina membentangkan tikar di teras, mengeluarkan tampah, dan membuka daun pintu lumbung lebar-lebar. Sekali ia menoleh ke arah jalan kantor, lalu kembali kepada timbangan. Dua penanam datang bergantian dengan kartu masing-masing; ia menakar benih, mengikat bungkusnya dengan tali rafia, dan menerima uang pas dari keduanya.'] },
      { chapterNumber: 48, title: 'Teh Hangat Dituang', paragraphs: ['Danu menuang teh ketika Vina menyebutkan kegelisahannya lagi di meja dapur. Kakaknya mengangguk, meniup uap dari cangkirnya, dan berpindah ke harga kayu bakar yang naik dua ratus rupiah. Mereka menyusun rencana belanja pasar Sabtu. Setelah cangkir kosong, Vina memasukkan kartu jatah air ke laci meja dan mendorongnya menutup dengan pinggul.'] },
      { chapterNumber: 49, title: 'Senja Tanpa Utusan', paragraphs: ['Senja menurunkan warna ungu pada teras dan pematang di bawahnya. Vina berdiri lama menghadap jalan yang menanjak, mendengarkan. Seekor kambing tetangga lewat menyeret talinya sendiri, lalu berhenti mengunyah daun pagar. Vina menaburkan dedak untuk ayam, mengangkat jemuran yang masih hangat, dan masuk. Lampu-lampu rumah di lereng seberang menyala satu per satu.'] },
      { chapterNumber: 50, title: 'Angin Kembali Biasa', paragraphs: ['Angin puncak menggoyang daun dengan kekuatan yang sama seperti pekan lalu. Vina bekerja sepanjang pagi menakar dan mengikat, lalu giliran airnya masuk sesuai angka pada kartu. Ia turun ke pasar membeli sawi dan sebungkus teri. Keranjang belanja bergoyang pada lengannya sampai tikungan rumah, tempat Danu sedang membetulkan tali sandalnya di tangga.'] },
    ], justification: 'Across Bab 33–50 Vina only ever thinks about Bagas while sweeping, drying seed, weighing orders, and shopping. Her card keeps the same figure, her turn arrives on schedule, buyers pay in full, and nobody from the office ever comes, asks, or sets a date.' },
    { chapters: [
      { chapterNumber: 33, title: 'Noda pada Tumit', paragraphs: ['Vina menemukan noda lumpur pada tumitnya seusai menyeberangi teras. Sambil menggosoknya di pancuran, ia menduga ada rembesan dari saluran hulu, meski tidak berjalan naik untuk melihat. Air pancuran mengalir deras dan dingin di telapaknya. Tanaman cabai di bedeng depan berdiri tegak, dan bunyi aliran di belakang rumah terdengar sama sampai matahari tenggelam di balik punggung bukit.'] },
      { chapterNumber: 34, title: 'Jejak Ayam Membekas', paragraphs: ['Hujan semalam membuat halaman lunak sehingga jejak ayam tercetak di mana-mana. Vina mengikuti dua tapak dengan mata, lalu dugaan tentang kebocoran itu muncul lagi di kepalanya. Jejak berakhir di depan kandang, tempat dedak kemarin masih tersisa di palung kayu. Ia menambah taburan baru, menghitung ayamnya sampai genap sebelas, dan menyapu lumpur lunak itu ke tepi supaya tapak berikutnya tidak tercetak di jalan masuk.'] },
      { chapterNumber: 35, title: 'Pematang Terasa Lembek', paragraphs: ['Sepotong pematang terasa lembek dan turun sejengkal di bawah sandal Vina. Ia membayangkan rembesan yang menyelinap di dalam tanah, walaupun seluruh lereng memang baru diguyur hujan. Danu menancapkan ranting sebagai penanda dan menekan tanah dengan tumit. Pagi berikutnya ranting itu masih tegak di tempatnya semula, dan setiap petak menerima airnya menurut giliran biasa.'] },
      { chapterNumber: 36, title: 'Sandal Dicuci Kembali', paragraphs: ['Lumpur menempel lagi pada tali sandal setelah Vina menyeberangi kebun. Ia mencucinya di bawah pancuran sambil mengulangi dugaannya dalam hati. Airnya bening dan menghantam ember dengan bunyi keras. Setelah tali sandal bersih, ia menaruhnya miring di dekat tungku agar cepat kering, kemudian menakar benih untuk dua pesanan yang harus diambil esok pagi.'] },
      { chapterNumber: 37, title: 'Genangan Selebar Tampah', paragraphs: ['Genangan selebar tampah terbentuk di dekat tangga rumah. Vina mengira air itu datang dari pipa hulu, sampai ia melihat talang menetes tepat di atasnya. Ia menggeser tempayan ke bawah tetesan dan menahan bibirnya dengan batu supaya tidak bergulir di tanah miring. Menjelang siang genangan itu tinggal cincin lumpur kering, sedangkan tempayan sudah terisi sampai sepertiga dan cukup untuk membasahi bedeng cabai di sisi tangga.'] },
      { chapterNumber: 38, title: 'Tanah Mengering Cepat', paragraphs: ['Matahari mengeringkan halaman sampai tapak kemarin hilang seluruhnya. Vina menoleh ke arah saluran ketika membentangkan kain tenun di tali jemuran. Di sana seekor capung hinggap pada tiang pembagi. Ia membalik kain dua kali sepanjang siang, melipatnya sore hari, lalu masuk untuk melanjutkan hitungan karung yang tertunda sejak kemarin.'] },
      { chapterNumber: 39, title: 'Batu Tertutup Lumut', paragraphs: ['Lumut hijau tebal menutupi sebuah batu di sisi pematang. Vina menekannya dengan ibu jari dan berpikir tempat itu mungkin sering dilalui rembesan. Batu tersebut memang duduk beberapa langkah dari pancuran lama. Ia membasuh tangan, memikul dua karung benih ke rumah tetangga, dan pulang membawa sekantong kacang tanah sebagai penukar.'] },
      { chapterNumber: 40, title: 'Dugaan Saat Gerimis', paragraphs: ['Gerimis membuat jalan berlumpur lagi menjelang sore. Vina menyebutkan kemungkinan saluran bocor kepada Danu, yang menunjuk awan tebal di puncak sambil tertawa dan berkata hujannya yang bocor. Mereka pulang memikul daun petikan yang basah. Di dapur, Vina merebus air sementara Danu menjemur kaus di dekat bara, dan percakapan berpindah ke ongkos gerobak.'] },
      { chapterNumber: 41, title: 'Lumpur di Sandal Kiri', paragraphs: ['Vina menemukan lumpur pada sandal kirinya setelah pulang dari pematang dan mengira saluran mungkin bocor. Ia membersihkannya di pancuran sambil mengingat cerita warga tentang pintu yang sering macet. Tidak ada pintu yang dilihat, tidak ada air yang berkurang, dan tidak ada orang yang memberi kabar. Setelah sandal kering, ia meletakkannya di bawah ranjang seperti biasa.'] },
      { chapterNumber: 42, title: 'Talang Menetes Lagi', paragraphs: ['Hujan pendek siang itu membuat talang menetes lagi di samping pintu. Vina memandangi bekas lumpur di halaman dan pikirannya berjalan naik ke hulu. Ia menaruh baskom seng di bawah tetesan dan mendengarkan bunyinya berubah saat dasar baskom tertutup air. Isinya cukup untuk menyiram dua rumpun bunga kertas di tepi tangga sebelum petang.'] },
      { chapterNumber: 43, title: 'Lumpur Kembali di Halaman', paragraphs: ['Pagi berikutnya lumpur baru terlihat di halaman setelah hujan malam, lalu Vina kembali memikirkan kemungkinan saluran bocor. Ia menelusuri dua langkah di depan rumah dan tidak menemukan apa pun selain jejak ayam. Karsa lewat menjual bibit, tetapi mereka hanya membahas cuaca. Siang berlalu, sandal dibersihkan lagi, dan dugaan tentang saluran tidak menjadi masalah yang harus dihadapi siapa pun.'] },
      { chapterNumber: 44, title: 'Ayam Mengais Tanah', paragraphs: ['Ayam mengais tanah basah sampai lumpur terciprat ke anak tangga. Vina mengibaskan sapu untuk mengusirnya, lalu berdiri memandang lereng di seberang jurang. Kabut menggantung di antara barisan teh. Ia mengangkat empat tampah dari dalam, menjajarkannya di halaman untuk dijemur, dan membalik dua di antaranya ketika sisi atasnya terasa hangat oleh matahari.'] },
      { chapterNumber: 45, title: 'Pancuran Tetap Deras', paragraphs: ['Vina menyodorkan kendi ke bawah pancuran dan memperhatikan air yang menghantam mulutnya sampai meluap. Dugaan tentang rembesan masih tersimpan di kepalanya. Seorang tetangga jongkok di sebelahnya mencuci sawi sambil mengeluh harga cabai. Mereka bertukar kabar tentang panen singkong, kemudian memikul kendi masing-masing menaiki tangga batu ke rumah.'] },
      { chapterNumber: 46, title: 'Lumpur Kering di Pematang', paragraphs: ['Beberapa hari kemudian lumpur di pematang telah mengering dan Vina tetap membayangkan ada kerusakan di hulu. Ia tidak pergi memeriksa karena pekerjaan menjemur daun teh lebih mendesak, meski tidak ada kerusakan yang dibuktikan. Danu mengangkat bahu ketika mendengarnya. Sore itu semua petak menerima air seperti biasa, dan dugaan Vina menguap tanpa menambah tekanan bagi dirinya atau orang lain.'] },
      { chapterNumber: 47, title: 'Retak Tanah Sangat Tipis', paragraphs: ['Sebuah garis setipis rambut membelah tanah kering dekat kandang. Vina menelusurinya dengan ujung gagang sapu, lalu menyiramkan sisa air cucian sampai garis itu tertutup lumpur. Ia menancapkan ranting di ujungnya sebagai penanda. Danu berangkat memetik pada jam biasa, dan sore harinya cabai di bedeng sebelah masih berdaun tebal ketika Vina memetik tiga buah untuk sambal.'] },
      { chapterNumber: 48, title: 'Hujan Menghapus Jejak', paragraphs: ['Hujan deras menghapus semua tapak di halaman dan merobohkan ranting penanda itu. Vina duduk di dekat jendela menambal keranjang rotan yang berlubang di dasarnya sambil memikirkan kebocoran yang belum pernah ia lihat sendiri. Air turun melalui talang, masuk selokan, dan menghilang ke bawah pagar. Ketika hujan reda, ia mengganti alas kaki di serambi dan keluar melihat tempayan.'] },
      { chapterNumber: 49, title: 'Sandal Kering di Tungku', paragraphs: ['Sandal Vina mengering di dekat tungku sepulang dari pasar, talinya kaku oleh panas. Ia memeriksa solnya, menekan bagian tumit yang menipis, lalu menaruhnya di bawah bangku panjang. Kartu jatah air kembali ke paku dan arit tergantung pada pasak dinding. Danu memiringkan sandalnya sendiri di sisi lain tungku sebelum menutup pintu dapur.'] },
      { chapterNumber: 50, title: 'Pematang Dilalui Biasa', paragraphs: ['Vina menyusuri pematang yang sama sambil memanggul keranjang berisi bungkusan benih. Tanahnya keras dan menahan langkah dengan baik. Ia menyerahkan pesanan di teras pembeli, menghitung uang di telapak tangan, lalu pulang mendahului kabut. Sore itu airnya masuk sesuai giliran, dan ia menutup pintu petak kecil setelah alur terakhir mencapai akar cabai.'] },
    ], justification: 'Mud, chicken tracks, a dripping gutter, and soft embankment keep reviving the same leak theory that Vina never walks upstream to test. Every turn arrives, every delivery is paid, the fountain runs hard, and nobody ever asks her for anything.' },
    { chapters: [
      { chapterNumber: 33, title: 'Pipit Mematuk Gabah', paragraphs: ['Sekawanan pipit mematuki gabah yang tercecer di atap lumbung. Dari jalan di bawah terdengar potongan percakapan yang menyebut nama Bagas, lalu suaranya tertelan bunyi langkah. Vina berhenti menyapu untuk mendengarkan, kemudian meneruskan sapuan sampai ke tangga. Daun pintu gudang dibiarkan terbuka hingga petang agar udara lembap keluar, dan ia menutupnya saat lampu tetangga menyala.'] },
      { chapterNumber: 34, title: 'Sayap di Talang Bambu', paragraphs: ['Dua burung hinggap di talang ketika Vina mencuci tampah dengan sikat ijuk. Nama yang terdengar kemarin muncul lagi di kepalanya bersama bayangan urusan saluran. Bu Ningsih datang meminjam jarum dan sepotong benang hitam untuk menambal kain tenun yang sobek pada bagian pinggir. Mereka duduk di tangga membicarakan cara menjahit tepi kain sampai matahari condong.'] },
      { chapterNumber: 35, title: 'Sarang Dekat Cerobong', paragraphs: ['Pipit membawa rumput kering ke sarangnya di sudut cerobong. Vina memperhatikan bolak-balik burung itu sambil menjemur benih, dan perasaan bahwa sesuatu sedang terjadi di kantor kembali menyentuhnya. Ia memeriksa kusen pintu yang mulai lapuk, kemudian mengikat bungkusan daun petikan yang akan dibawa Danu ke pasar. Tampah digeser mengikuti matahari sampai bayang pohon memanjang.'] },
      { chapterNumber: 36, title: 'Kicau Membuka Pagi', paragraphs: ['Kicau pipit membangunkan Vina lebih awal daripada lonceng kebun. Semalam ia bermimpi tentang Bagas, maka pagi itu kartu jatah air diturunkan dari paku dan dibacanya di bawah cahaya jendela; angka dan capnya seperti kemarin. Danu berangkat membawa bekal singkong rebus. Vina membuka lumbung, melepas ikatan tampah pertama, dan melayani pembeli yang datang paling pagi.'] },
      { chapterNumber: 37, title: 'Bulu Jatuh di Pagar', paragraphs: ['Sehelai bulu tersangkut pada bilah pagar dan bergetar tertiup angin. Vina memungutnya, memutarnya di antara jari, lalu menatap tanjakan berbatu menuju kantor. Ia menduga nama itu akan kembali terdengar hari ini. Yang muncul di tikungan justru Karsa dengan gerobak bibitnya; mereka menawar harga cabai rawit dan berpisah setelah sepakat pada angka tengah.'] },
      { chapterNumber: 38, title: 'Burung Mandi Debu', paragraphs: ['Sekawanan burung berguling-guling di debu halaman saat matahari sedang terik. Vina membayangkan seorang petugas datang mengusir mereka, lalu tersenyum sendiri pada bayangannya. Ia menabur segenggam gabah di dekat pagar supaya burung menjauh dari tampah. Setelah kawanan itu terbang ke rumpun bambu, ia menutup wadah benih dengan kain dan membawanya masuk.'] },
      { chapterNumber: 39, title: 'Pipit Terbang Melingkar', paragraphs: ['Seekor pipit terbang melingkar di atas teras sebelum turun ke kebun. Vina mengikuti putarannya dengan mata sampai burung itu lenyap di sela pohon teh. Ia menutup daun jendela agar debu tidak masuk, lalu menakar benih pesanan Bu Ningsih di atas timbangan kecil. Udara di dalam menjadi panas, maka jendela itu dibukanya lagi selebar sejengkal.'] },
      { chapterNumber: 40, title: 'Nama Terdengar Samar', paragraphs: ['Beberapa orang berbicara di jalan, dan Vina menangkap nama Bagas satu kali di antara suara mereka. Ketika ia mendekat membawa keranjang, percakapan sudah berpindah ke harga singkong basah. Ia ikut berdiri di situ sebentar, menyebut harga benih kacangnya, lalu pulang. Seorang pembeli menyusul di pematang dan mengulang pesanan yang kemarin belum jelas jumlahnya.'] },
      { chapterNumber: 41, title: 'Burung Pipit di Atap', paragraphs: ['Sekawanan pipit turun ke atap lumbung dan mematuki remah gabah yang tersisa di talang. Vina mendengar orang menyebut Bagas di jalan, lalu merasa urusan air mungkin akan memburuk. Ia tidak mengetahui hal baru dan tidak menerima perintah apa pun. Setelah burung terbang, ia masuk untuk merapikan tampah sambil menyimpan rasa tidak enak yang sama.'] },
      { chapterNumber: 42, title: 'Remah Gabah Disapu', paragraphs: ['Vina naik ke atap rendah lumbung dan menyapu remah gabah dari talang supaya pipit tidak berkumpul terlalu banyak. Ucapan yang terdengar di jalan itu berputar lagi di kepalanya, meski wajah pembicaranya tetap tak dikenalinya. Mbah Ripto lewat menenteng ketel tembaga dan menyapa dari bawah. Vina turun, menyandarkan sapu di dekat pintu, lalu membasuh tangannya.'] },
      { chapterNumber: 43, title: 'Pipit Hinggap di Pagar', paragraphs: ['Pipit yang sama hinggap di pagar bambu ketika Vina menjemur kain lap. Ia teringat lagi bahwa nama Bagas disebut dua hari lalu dan membayangkan kemungkinan yang tidak dijelaskan siapa pun. Bu Ningsih datang mengantar buku, tetapi percakapan mereka berhenti pada resep singkong. Tidak ada surat masuk, pintu tertutup, atau ancaman yang memaksa Vina meninggalkan pekerjaan sore itu.'] },
      { chapterNumber: 44, title: 'Buku Resep Dibaca', paragraphs: ['Vina membuka buku resep pinjaman Ningsih di meja teras sementara burung-burung berpindah sepanjang bilah pagar. Pikirannya sesekali menyimpang kepada Bagas, lalu kembali kepada barisan takaran. Ia menyalin ukuran gula merah dan kelapa parut ke sobekan kertas, menandainya dengan potongan arang, kemudian menutup buku. Sore itu ia menanak singkong menurut takaran tersebut dan Danu menghabiskan dua potong.'] },
      { chapterNumber: 45, title: 'Sarang Tetap Utuh', paragraphs: ['Angin menggoyang sarang di sudut cerobong sampai rumput keringnya berjatuhan, tetapi sarang itu bertahan. Vina memasang dua ranting penahan di bawahnya sambil memikirkan urusan air sekali lagi. Kartu jatahnya masih berlaku sampai akhir bulan. Ia membalik benih yang dijemur agar sisi bawahnya kena matahari, lalu membawa seluruh tampah masuk ketika gerimis mulai turun.'] },
      { chapterNumber: 46, title: 'Pipit Terbang ke Sawah', paragraphs: ['Ketika pipit terbang menuju sawah, Vina berdiri memandangi jalurnya dan kembali merasa ada sesuatu yang tidak baik dalam urusan saluran. Ia memeriksa kartu jatah, lalu menyimpannya sebab angkanya tetap. Mbah Ripto tidak muncul hari itu. Menjelang malam, ia mengunci lumbung dan tidur, sementara keadaan tetap selapang tiga hari sebelumnya.'] },
      { chapterNumber: 47, title: 'Ripto Datang Membawa Ketel', paragraphs: ['Mbah Ripto muncul keesokan pagi membawa ketel tembaganya yang sudah bertambal, bercerita bahwa kemarin ia menunggu seharian di bengkel pandai besi. Vina menyiapkan tiga cangkir di meja teras dan menuangkan air panas. Mereka membicarakan harga timah patri dan cuaca di lereng atas. Setelah cangkirnya kosong, Ripto menuruni jalan sambil menjinjing ketel itu di tangan kiri.'] },
      { chapterNumber: 48, title: 'Anak Pipit Belajar Terbang', paragraphs: ['Seekor anak pipit mengepak dari cerobong ke arah pagar, lalu jatuh ke rumpun daun pisang yang basah. Vina menangkupkan telapak tangan di sekelilingnya dan menaruhnya kembali di lekuk atap. Burung itu mencoba lagi dua kali sepanjang pagi. Vina berdiri memperhatikan sambil memegang kain lap, memikirkan kantor saluran sekali lagi, dan pekerjaan menakar baru dimulai menjelang siang.'] },
      { chapterNumber: 49, title: 'Pagar Bambu Diperbaiki', paragraphs: ['Danu mengikat bilah pagar yang longgar dengan tali rafia berlapis dua, sementara pipit berpindah ke bubungan atap. Vina memegangi batang bambu agar tidak bergeser dan sesekali melirik jalan di bawah. Seorang pedagang sayur lewat menawarkan kubis dan berhenti untuk minum. Danu menarik simpulnya sampai kencang, mengujinya dengan goyangan, lalu menggulung sisa tali.'] },
      { chapterNumber: 50, title: 'Pipit Kembali ke Talang', paragraphs: ['Pipit kembali mematuki talang ketika Vina membuka daun pintu lumbung. Ia menaburkan remah gabah jauh dari pintu supaya burung-burung turun ke tanah dan tidak menghambur di dekat timbangan. Kartu jatah tergantung utuh pada pakunya. Pembeli pertama datang membawa kantong kain, dan Vina menimbangkan dua bungkus benih untuknya sebelum kabut naik.'] },
    ], justification: 'Pipits, a stray mention of Bagas on the road, and Vina’s unease recur for eighteen chapters while she sweeps, dries seed, copies a recipe, and mends a fence. Her card, gate, route, stock, and buyers stay exactly as they were, and nobody from the office ever arrives.' },
    { chapters: [
      { chapterNumber: 33, title: 'Bara Merah di Tungku', paragraphs: ['Bara merah berdenyut di bawah tampah pengering ketika Vina mengaduk sekam dengan bilah kayu. Daun pintu berderit dan ia menoleh cepat ke arah jalan, tetapi Danu yang masuk memikul kayu bakar. Panas tersebar merata sampai ke tepi tampah, benih mengering, dan asap keluar lewat cerobong. Ia menutup pintu setelah tampah terakhir diangkat.'] },
      { chapterNumber: 34, title: 'Asap Membentuk Lingkaran', paragraphs: ['Asap keluar membentuk lingkaran-lingkaran kecil sebelum pecah di udara dingin. Vina menatapnya dan bertanya-tanya apakah jadwal air akan diubah bulan ini. Papan pengumuman di simpang masih memuat daftar harga pasar yang sama sejak pekan lalu. Danu datang membawa ikatan kayu tambahan, dan mereka menumpuknya di sisi tungku untuk dipakai besok pagi.'] },
      { chapterNumber: 35, title: 'Sekam Diaduk Pelan', paragraphs: ['Vina mengaduk sekam perlahan supaya panasnya tidak melonjak dan merusak kulit benih. Kekhawatiran tentang Bagas muncul lagi ketika daun pintu berderit, lalu ia melihat angin yang mendorongnya. Ia mengganjal pintu itu dengan batu kali sebesar kepalan. Pekerjaan berlanjut sampai seluruh tampah dapat diangkat, dan ia meratakan sisa campuran memakai bilah kayu.'] },
      { chapterNumber: 36, title: 'Cerobong Disapu Jelaga', paragraphs: ['Jelaga menebal di dinding cerobong, maka Vina menyapunya memakai seikat ranting yang diikat pada galah. Debu hitam turun dan membuatnya bersin tiga kali. Ia sempat menghubungkan warna itu dengan firasatnya tentang kantor, lalu tertawa pada dirinya sendiri. Jelaga yang jatuh ditampung ke dalam tempurung, dibuang ke kebun, dan tungku dinyalakan lagi menjelang siang.'] },
      { chapterNumber: 37, title: 'Kayu Kering Ditumpuk', paragraphs: ['Danu menyusun kayu kering setinggi lutut di sepanjang dinding dapur, menyisakan lorong menuju pintu. Vina menghitung tumpukan itu sambil mengingat pertanyaannya tentang jadwal; kakaknya menjawab belum mendengar apa-apa dari kebun. Mereka menutupi kayu dengan kain agar embun tidak masuk, lalu duduk di halaman memakan singkong rebus sampai kabut turun.'] },
      { chapterNumber: 38, title: 'Uap Ketel Naik', paragraphs: ['Uap ketel tembaga naik di depan wajah Vina yang menunggu air mendidih untuk teh. Ia membayangkan kantor mengirim surat pemberitahuan, lalu mengecilkan api ketika ketel mulai bersiul. Teh dituangkan ke dua gelas dan diberi gula sepotong. Sore itu Danu bercerita tentang petak paling atas yang hasilnya naik sejak hujan sering turun.'] },
      { chapterNumber: 39, title: 'Api Menyala Stabil', paragraphs: ['Api menyala rata sepanjang waktu pengeringan. Vina menjenguk bara tiga kali sambil memikirkan perubahan yang mungkin dibuat Bagas. Danu pulang membawa kabar bahwa pengepul menaikkan harga daun basah lima puluh rupiah. Benih yang diangkat dari tampah terasa kering dan ringan di telapak, lalu Vina menakarnya ke dalam karung goni sesuai pesanan.'] },
      { chapterNumber: 40, title: 'Jelaga Menempel Kain', paragraphs: ['Kain penutup tampah tergesek cerobong dan pulang dengan garis jelaga sepanjang lengan. Vina membilasnya di tempayan belakang, mengucek bagian yang hitam dua kali, lalu memerasnya sampai airnya bening. Selama tangannya bekerja, ingatannya berjalan lagi ke arah kantor. Kain itu ia bentangkan di tali jemuran dan sudah kering sebelum lampu dapur dinyalakan.'] },
      { chapterNumber: 41, title: 'Asap Tipis dari Tungku', paragraphs: ['Asap tipis keluar dari tungku pengering dan Vina mengira bara mungkin kurang baik. Ia mengaduk sekam, menunggu sebentar, lalu kembali memikirkan apakah kantor saluran akan mengubah jadwal. Tidak ada pemberitahuan dari kantor. Benih tetap kering, tungku tetap menyala, dan ia hanya memindahkan kekhawatiran dari satu pikiran ke pikiran berikutnya.'] },
      { chapterNumber: 42, title: 'Ranting Patah Terbakar', paragraphs: ['Sebatang ranting patah dan meletup ketika dimasukkan ke dalam api. Bunyinya membuat Vina menoleh ke pintu, lalu ia melihat halaman kosong dan seekor kucing tidur di atas karung. Ia menata ulang susunan kayu supaya nyalanya merata, kemudian menyelesaikan pengeringan dua tampah. Di dinding seberang, kartu jatahnya menggantung pada paku lama dengan angka yang belum diubah.'] },
      { chapterNumber: 43, title: 'Asap Menempel di Langit', paragraphs: ['Langit di atas tungku tampak kelabu karena asap dan Vina merasa hari itu terlalu lambat berlalu. Ia bertanya kepada Danu apakah ia mendengar kabar dari kantor, tetapi kakaknya menjawab belum. Mereka lalu diam sambil menunggu air mendidih. Tidak ada aturan baru, orang baru, atau kerugian yang muncul dari percakapan tersebut sebelum mereka makan malam.'] },
      { chapterNumber: 44, title: 'Abu Dibawa Angin', paragraphs: ['Angin mengangkat abu dari mulut tungku dan menyebarkannya tipis di rumput halaman. Vina menyapunya ke satu tumpukan sambil merasa kabar dari kantor mungkin tiba hari ini. Karsa lewat di jalan bawah mendorong gerobak bibit menuju pasar dan melambaikan tangan tanpa berhenti. Vina menaburkan abu itu ke pangkal pohon pepaya, lalu menutup wadah sekam di sudut.'] },
      { chapterNumber: 45, title: 'Tampah Disusun Rapi', paragraphs: ['Tampah yang sudah kering disusun berdiri sepanjang dinding. Vina meraba permukaan tiap anyaman untuk mencari serat yang mencuat, menghitungnya sampai empat belas, lalu duduk di bangku dekat tungku. Pertanyaan lama tentang jadwal muncul lagi dan lewat begitu saja. Dari jalan terdengar anak-anak pulang sekolah, dan ia memadamkan bara sebelum menutup pintu.'] },
      { chapterNumber: 46, title: 'Asap Hilang di Sore Hari', paragraphs: ['Sore berikutnya asap sudah hilang dan tungku bekerja seperti biasa. Vina masih mengingat pertanyaannya tentang kantor saluran, lalu memutuskan mungkin kabar akan datang sendiri. Ia melipat kain, menyimpan alat, dan menutup pintu. Keesokan hari belum diberi bentuk oleh peristiwa apa pun, sebab tidak ada tekanan yang meningkat dari awal sampai akhir rangkaian.'] },
      { chapterNumber: 47, title: 'Pintu Tungku Dibuka', paragraphs: ['Vina membuka mulut tungku setelah baranya dingin sejak semalam. Abu yang tersisa setebal jari ia sendok ke dalam ember dan tuang di sekeliling pohon jeruk. Sekali ia menoleh ke tanjakan menuju kantor sambil menyeka dahi. Pada kusen lumbung hanya menempel jelaga tipis bekas musim lalu, dan Mbah Ripto membantunya mengaitkan palang pengering ke dinding.'] },
      { chapterNumber: 48, title: 'Kayu Baru Diantar', paragraphs: ['Penjual kayu datang mengantar pesanan dengan gerobak pagi hari, dan Vina membayar dengan harga yang sama seperti bulan lalu. Ia bercerita tentang jalan pasar yang berlubang, bukan tentang kantor. Danu memeriksa tiap batang, menyisihkan yang masih lembap ke teras, lalu menumpuk sisanya di bawah atap dapur dan menutupinya dengan terpal biru.'] },
      { chapterNumber: 49, title: 'Ketel Dibasuh Bersih', paragraphs: ['Ketel dibasuh dengan abu halus dan serabut kelapa setelah teh sore, sampai bagian dasarnya kembali mengkilap. Vina bertanya sekali lagi apakah Danu mendengar perubahan jadwal, dan kakaknya menggeleng sambil mengeringkan tangan. Air bilasan disiramkan ke bedeng cabai. Ketel diletakkan telungkup di dekat jendela, lalu lampu dapur dipadamkan.'] },
      { chapterNumber: 50, title: 'Tungku Menyala Kembali', paragraphs: ['Tungku dinyalakan lagi untuk pesanan berikutnya sebelum matahari naik. Vina mengaduk sekam, mengukur panasnya dengan punggung telapak, dan mengangkat benih tepat ketika kulitnya mengeras. Mbah Ripto singgah membawa dua pekerja saluran yang kehausan, dan mereka menuang air ketel ke cangkir bergantian. Pembeli datang siang itu, memikul karungnya, dan membayar penuh di teras.'] },
    ], justification: 'Eighteen chapters of stoking, sweeping soot, stacking wood, and asking Danu the same question keep Vina’s worry about the office private. Fuel is bought at the usual price, seed dries on time, buyers pay in full, and no order, letter, or date ever reaches her.' },
    { chapters: [
      { chapterNumber: 33, title: 'Daun Gugur di Jalan', paragraphs: ['Daun teh yang gugur menutupi jalan sempit menuju rumah jaga sampai batu-batunya tak kelihatan. Vina menyapunya ke tepi sambil membayangkan Bagas melarang orang melintas di sana. Sapuannya berhenti di mulut tikungan. Setelah daun terkumpul menjadi dua gundukan, ia menyusuri jalan itu untuk mengantarkan ketel tembaga kepada Mbah Ripto dan pulang membawa mangkuk kosong.'] },
      { chapterNumber: 34, title: 'Ranting Menyentuh Pagar', paragraphs: ['Sebatang ranting tertiup angin dan mengetuk pagar dekat saluran. Bunyinya membuat Vina berhenti di tengah tanjakan, mengira ada petugas berdiri di balik rumpun. Ia mendekat dan menemukan ranting itu patah setengah, masih menempel pada dahannya. Vina mematahkannya sampai lepas, melemparkannya ke selokan, kemudian melanjutkan langkah sambil menenteng bungkusan benih pesanan.'] },
      { chapterNumber: 35, title: 'Selokan Penuh Daun', paragraphs: ['Daun basah menumpuk di tepi selokan tanpa menahan alirannya. Vina memperhatikannya sambil memikul pesanan ke rumah Bu Ningsih. Dari tikungan terdengar dua pemetik di belakangnya membicarakan hasil petak paling atas, dan mereka menyusul di tanjakan. Ketiganya berjalan beriringan sampai simpang, lalu berpisah ketika warung di ujung jalan baru membuka daun pintunya.'] },
      { chapterNumber: 36, title: 'Gerbang Terlihat Jauh', paragraphs: ['Dari teras atas, gerbang rumah jaga hanya tampak sebagai garis bambu tipis di antara kabut. Vina membayangkan dua kru berdiri di sana memeriksa orang lewat, tetapi yang bergerak hanya kain jemuran Ripto. Ia menuruni jalan itu membawa mangkuk yang harus dikembalikan, menyerahkannya di teras, dan pulang mendaki sebelum kabut menutup pematang.'] },
      { chapterNumber: 37, title: 'Keranjang Melintas Aman', paragraphs: ['Vina memanggul keranjang penuh bungkusan benih melalui tikungan dekat saluran. Bayangan tentang larangan lewat membuat langkahnya melambat pada bagian yang menikung. Seorang anak berlari dari arah berlawanan sambil mengacungkan kincir bambu, dan mereka berpapasan di tempat sempit. Vina sampai di rumah pembeli dengan isi keranjang utuh, lalu menghitung uang di tangga.'] },
      { chapterNumber: 38, title: 'Hujan Membasahi Jalur', paragraphs: ['Hujan membasahi jalan sampai daun-daun melekat pada sol sandalnya. Vina berteduh di bawah rumpun bambu dan memikirkan penjaga yang mungkin muncul di tikungan bawah. Air menetes dari ruas bambu ke tengkuknya. Hujan berhenti lebih cepat daripada dugaannya, dan ia pulang sambil mengibaskan daun dari kaki setiap beberapa langkah.'] },
      { chapterNumber: 39, title: 'Batu Jalan Disusun', paragraphs: ['Mbah Ripto menyusun batu kali pada bagian jalan yang licin, memilih yang permukaannya rata. Vina mengangkat batu dari selokan dan menyerahkannya satu per satu sambil bertanya apakah kantor berencana menempatkan penjaga di jalur itu. Ripto menggeleng dan menekan batu terakhir dengan tumit. Mereka mencoba melintas bergantian, lalu berpisah ketika lonceng makan berbunyi.'] },
      { chapterNumber: 40, title: 'Bayang Bambu Memanjang', paragraphs: ['Bayang rumpun bambu memanjang melintang di jalan ketika Vina pulang menjelang petang. Dari kejauhan bentuknya menyerupai palang, lalu buyar begitu angin menggeser batangnya. Ia melewati garis bayangan itu dan terus mendaki sampai lumbung. Di kusen pintu masih terselip daun sirih kering dari pekan lalu, maka ia meneruskan langkah ke rumah Ningsih untuk mengambil buku pinjaman.'] },
      { chapterNumber: 41, title: 'Daun Teh Menutup Jalan', paragraphs: ['Daun teh yang jatuh menumpuk di jalan kecil menuju rumah jaga, dan Vina menyapu sebagian dengan ranting. Ia membayangkan Bagas mungkin tidak suka melihat orang mendekati saluran, tetapi tidak ada larangan atau penjaga. Jalan tetap terbuka setelah daun dipindahkan. Vina kembali ke lumbung, menyelesaikan hitungan karung, dan tidak perlu mengubah rencana hari itu.'] },
      { chapterNumber: 42, title: 'Sapu Ranting Disimpan', paragraphs: ['Vina menyandarkan sapu ranting itu pada pagar supaya besok tinggal diambil. Matanya menyusuri jalan turun ke rumah jaga dan kekhawatiran kemarin muncul lagi sebentar. Dua warga melintas memanggul bambu panjang, berteriak minta jalan, lalu menuruni tikungan. Ia masuk ke lumbung, menimbang pesanan benih kacang, dan menyimpul bungkusnya memakai rafia hijau.'] },
      { chapterNumber: 43, title: 'Daun Basah di Selokan', paragraphs: ['Hujan mengalirkan daun basah ke selokan dekat jalan rumah jaga. Vina melihatnya dari jauh dan sekali lagi mengira orang kantor mungkin akan memperketat penjagaan. Ia tidak mendekat, tidak dicegat, dan tidak menerima kabar. Setelah hujan reda, ia membawa keranjang pulang sambil memikirkan hal yang sama tanpa memperoleh alasan baru untuk takut.'] },
      { chapterNumber: 44, title: 'Jalan Mengering Siang', paragraphs: ['Matahari siang mengeringkan permukaan jalan dan daun-daun yang tertinggal di celah batu. Vina melintas memanggul bakul kain cuci menuju pancuran. Ia menoleh ke rumah jaga: daun pintunya terbuka lebar dan Ripto sedang menjemur ketel di atas batu. Vina melambaikan tangan, meneruskan langkah, lalu merendam kain di bawah pancuran sampai busanya keluar.'] },
      { chapterNumber: 45, title: 'Kincir Bambu Berputar', paragraphs: ['Kincir bambu buatan anak-anak berputar di sisi saluran, memercikkan air ke rumput. Vina berhenti memperhatikannya dan bayangan tentang larangan kantor melintas lagi. Tiga anak berlari melewati gerbang sambil berteriak menghitung putaran. Ia meneruskan langkah ke kebun lereng, membuka pintu petaknya ketika giliran tiba, dan menunggu sampai air mencapai baris terakhir.'] },
      { chapterNumber: 46, title: 'Daun Kering Ditiup Pagi', paragraphs: ['Pagi cerah meniup daun kering melewati jalan yang masih terbuka menuju rumah jaga. Vina memandangi gerbang dari kejauhan, lalu memilih mengurus tampah di lumbung karena tidak ada yang mendesak. Bagas tidak tampak dan tidak ada perubahan pada air. Ketakutan yang dibayangkan tiga kali itu tidak menjelma menjadi rintangan, sehingga hari-harinya bergerak biasa saja.'] },
      { chapterNumber: 47, title: 'Ketel Ripto Dikembalikan', paragraphs: ['Vina membawa ketel yang sudah digosok bersih turun ke rumah jaga lewat jalan pendek. Ripto sedang menyapu teras ketika ia tiba dan langsung memeriksa gagang ketel itu, memutarnya untuk memastikan pakunya kencang. Mereka menyeduh air hangat dan meminumnya di anak tangga. Vina pulang membawa kain pembungkus yang kini kosong dan terlipat.'] },
      { chapterNumber: 48, title: 'Bambu Tumbang Disingkirkan', paragraphs: ['Angin malam merobohkan sebatang bambu muda melintang di tepi jalan. Vina memotong pucuknya dengan arit, lalu menyeret batangnya ke selokan bersama Danu sampai jalur itu lapang kembali. Keranjang petikan Danu lewat tanpa menyerempet. Dua pemetik yang menyusul dari bawah menyapa mereka dari tikungan dan meneruskan langkah menuju kebun atas.'] },
      { chapterNumber: 49, title: 'Selokan Dibersihkan Bersama', paragraphs: ['Empat warga mengeruk daun basah dan lumpur dari selokan sebelum hujan berikutnya turun. Vina ikut menyerok dengan tampah bocor dan memindahkan isinya ke keranjang pupuk. Mereka membicarakan panen singkong dan harga pupuk kandang sambil bekerja. Rumah jaga terlihat dari tikungan, dan seorang warga turun ke sana meminjam sekop tanpa perlu mengetuk.'] },
      { chapterNumber: 50, title: 'Jalan Kecil Tetap Terbuka', paragraphs: ['Vina menyusuri jalan kecil itu membawa dua bungkus benih ke teras atas. Sapu ranting masih bersandar pada pagar, dan sebuah kincir bambu kecil menderik pelan dekat mulut selokan. Ia menyerahkan pesanan tepat pada waktu yang dijanjikan, menerima uangnya, lalu turun melalui jalur yang sama. Danu menyusul di belakang memanggul keranjang lewat sisi kiri jalan.'] },
    ], justification: 'Leaves, a tapping branch, rain, and a bamboo shadow keep suggesting a blocked path that Vina only imagines being guarded. Ripto, children, pickers, and her own deliveries walk it in every chapter, and her turn, her card, and her orders run exactly as before.' },
  ],
  BORDERLINE: [
    { chapters: [
      { chapterNumber: 33, title: 'Daftar Simpan Diperiksa', paragraphs: ['Seorang juru tulis kantor gerbang menyalin isi rak lumbung ke dalam daftar simpan, lalu berhenti di pintu samping yang engselnya berkarat. Vina mengolesi engsel itu dengan minyak kelapa dan menekan palangnya dengan telapak sampai ujung kiri bergerak sejari. Juru tulis menuliskan sesuatu pada kolom paling kanan dan berkata Mandor Bagas membaca kolom itu setiap pekan.'] },
      { chapterNumber: 34, title: 'Tenggat Pertama Ditulis', paragraphs: ['Bagas mengirim catatan lewat juru tulis yang sama: palang pintu samping harus terpasang sebelum pasar berikutnya, atau baris lumbung Vina disisihkan dari daftar simpan sampai diperiksa ulang. Angin malam menggeser ujung palang dari lubangnya, tetapi daunnya tertahan batu, dan karung di rak dalam masih tersusun menurut urutan semula. Vina meminta Danu mencari kayu bila turun ke pasar.'] },
      { chapterNumber: 35, title: 'Batu Penahan Retak', paragraphs: ['Batu penahan retak ketika terinjak Vina, sehingga ia menggantinya dengan bongkah dari tungku lama yang tak dipakai. Pintu masih dapat ditutup dari dalam. Mbah Ripto naik membawa sisa rafia karung goni dan mengikat gagang itu ke tiang bersamanya, dua lilitan pada tiap ujung, sambil menghitung berapa hari tersisa sebelum pasar berikutnya dibuka.'] },
      { chapterNumber: 36, title: 'Rafia Menegang Malam', paragraphs: ['Hembusan lereng kuat membuat rafia menegang sepanjang malam. Vina bangun dua kali untuk meraba simpul itu dengan jari, lalu berbaring lagi menghitung sisa hari pada catatan kantor. Daun pintu tetap rapat pada kusennya, tetapi tidurnya terpotong. Pagi hari ia terlambat membalik satu tampah anyaman bambu; benihnya tetap kering setelah dijemur satu jam lebih lama.'] },
      { chapterNumber: 37, title: 'Pasar Kehabisan Kayu', paragraphs: ['Danu pulang tanpa palang baru sebab pedagang kayu kehabisan potongan pendek, dan tukang hanya menawarkan papan utuh berharga mahal. Pasar itu lewat sebelum kayunya ada. Vina menggandakan lilitan rafia, mencatat pesanan pada lembar belanja, lalu menyusun kalimat yang akan disampaikannya kalau juru tulis kembali membuka daftar simpan di halaman.'] },
      { chapterNumber: 38, title: 'Bagas Menyebut Tujuh Hari', paragraphs: ['Bagas berdiri di halaman lumbung dan menyebut tenggat baru: tujuh hari, terhitung sejak gerimis pagi itu. Ia tidak masuk dan tidak menyentuh apa pun. Simpul rafia mengendur oleh lembap, maka Vina mengikatnya dengan simpul rangkap dan menggeser dua karung goni menjauh dari pintu samping. Kedua karung menyempitkan lorong, sedangkan pembeli tetap masuk lewat pintu depan.'] },
      { chapterNumber: 39, title: 'Papan Bekas Diukur', paragraphs: ['Mbah Ripto membawa papan bekas yang sedikit terlalu pendek bagi lubang palang. Mereka mengukurnya, menambahkan ganjal bambu, dan menandai bagian yang harus dipotong memakai arang dapur. Pintu tertutup lebih rapat, namun papannya berderit bila ditekan. Ripto berkata ganjal itu hanya bertahan sampai kayu pasar tersedia, sementara hari keempat dari tujuh sudah lewat.'] },
      { chapterNumber: 40, title: 'Ganjal Bambu Terlepas', paragraphs: ['Ganjal bambu kuning terlepas saat Vina membuka pintu samping untuk membuang sekam ke kebun, maka ia memasangnya kembali dan menahannya dengan bongkah batu kali. Juru tulis berhenti di jalan bawah menghadap lumbung, memandang cukup lama, lalu meneruskan langkah tanpa naik. Malam itu angin melemah sampai daun jati diam, sehingga papan bekas bertahan sampai pagi.'] },
      { chapterNumber: 41, title: 'Pintu Kecil Tidak Terkunci', paragraphs: ['Pintu kecil di sisi lumbung terbuka saat Vina tiba pagi hari, padahal biasanya dipalang dari dalam. Ia memeriksa rak dan tidak menemukan karung hilang. Mbah Ripto menyarankan mengganti palang, tetapi Vina berkata akan melakukannya nanti setelah menjemur benih. Sepanjang hari pintu itu hanya menjadi keganjilan yang belum membawa akibat bagi siapa pun.'] },
      { chapterNumber: 42, title: 'Sisa Tiga Hari', paragraphs: ['Sehelai kertas dari kantor gerbang menempel pada tiang: tenggat tinggal tiga hari, dan baris yang belum berpalang akan diberi tanda saat daftar simpan dibuka. Vina menutup pintu kayu dengan dua lilitan rafia sebelum tidur, lalu Danu mendorongnya dari luar untuk menguji. Tali itu menahan, meski kayunya berbunyi. Mereka memindahkan satu karung goni dari teras sebagai berjaga-jaga.'] },
      { chapterNumber: 43, title: 'Palang Kayu Retak Sedikit', paragraphs: ['Palang pintu ternyata retak pada bagian tengah, namun masih bisa dipasang bila didorong kuat. Vina mengambil tali rafia dan mengikatnya sementara, lalu kembali bekerja. Danu berkata ikatan itu tidak akan tahan bila hujan besar datang. Mereka tidak punya kayu pengganti dan tidak mencari tukang. Ancaman ada, tetapi belum menentukan apa yang harus dikorbankan sebelum cuaca berubah.'] },
      { chapterNumber: 44, title: 'Gerimis Membasahi Kusen', paragraphs: ['Gerimis membasahi kusen dan membuat retakan memanjang selebar kuku. Vina mengangkat satu karung goni dari sisi teras ke papan rak paling atas, sehingga ruang untuk sebuah tampah anyaman bambu hilang dan pengeringan harus dilakukan bergantian sepanjang siang. Pesanan tetap selesai sebelum pembeli pasar datang, walau tenggat kantor tinggal semalam lagi dan kayunya belum ada.'] },
      { chapterNumber: 45, title: 'Hujan Besar Mendekat', paragraphs: ['Awan hitam berkumpul di puncak pada hari terakhir yang disebut Bagas. Danu menambah ikatan dari tali goni, menaruh tempayan sebagai penahan, dan memastikan simpul terakhir tidak bergeser sebelum gelap. Vina memindahkan karung goni paling dekat, tetapi membiarkan satu karung berat karena bahunya tidak sanggup mengangkatnya seorang diri. Hujan baru mulai setelah mereka tidur.'] },
      { chapterNumber: 46, title: 'Hujan Membuka Satu Karung', paragraphs: ['Hujan malam membuka pintu sedikit dan membasahi satu karung benih dekat teras. Vina memindahkannya ke dalam, tetapi sebagian butir telah lembek. Ia kehilangan satu karung, bukan seluruh simpanan, dan masih dapat menjual benih lain esok hari. Retakan palang kini harus diperbaiki, namun tidak ada orang yang melarang atau memaksa pilihannya lebih jauh.'] },
      { chapterNumber: 47, title: 'Baris Lumbung Ditandai', paragraphs: ['Juru tulis membentangkan lembar daftar itu di atas bangku teras dan memberi tanda pada baris lumbung Vina, lalu menyebut tenggat terakhir dari Bagas: kayu terpasang sebelum pasar lusa. Vina memilah butir lembek dari bagian yang masih keras dan menyelamatkan separuh karung goni. Ia mengembalikan uang satu pembeli pasar yang seharusnya menerima karung itu, kemudian menawarkan jadwal lusa yang sama.'] },
      { chapterNumber: 48, title: 'Kayu Baru Tiba', paragraphs: ['Pedagang pasar membawa potongan kayu setelah mendengar kebutuhan Vina, dan harganya setara laba satu karung goni. Danu memasang palang sebelum petang dingin sehingga pintu menutup lurus. Juru tulis datang menjelang gelap, menekan daun pintu dengan telapak, lalu mencabut tanda dari baris itu tanpa menuliskan hal lain pada kolom kanan.'] },
      { chapterNumber: 49, title: 'Pesanan Lusa Dipenuhi', paragraphs: ['Butir yang lolos pemilahan hanya cukup untuk setengah pesanan tertunda, maka Vina menambahnya dari persediaan rak lain dan menyerahkan jumlah penuh pada hari yang dijanjikan, tanpa biaya tambahan. Pembeli itu menerimanya di teras dan memesan lagi untuk pekan depan. Kas lumbung berkurang sebanyak harga kayu, sedangkan rak lain tetap terisi.'] },
      { chapterNumber: 50, title: 'Palang Baru Menahan', paragraphs: ['Hujan berikutnya memukul pintu kayu kecil dan palang baru tidak bergeser sedikit pun. Vina memeriksa teras setelah fajar: lantainya kering, seluruh karung goni utuh, dan lorong dalam kembali dipakai untuk tampah anyaman bambu. Ia memasukkan harga kayu itu ke buku perbaikan, lalu melipat kain yang dipakainya berjaga beberapa malam terakhir.'] },
    ], justification: 'Bab 33–50 carries a gate-office storage list: Bagas sets a market-day deadline, narrows it to seven days, to three, then to a final market, and a clerk marks the row before the wood arrives. Costs stay small — broken sleep, one wet sack half saved, one buyer served two days late, one sack of profit spent on wood — and the mark is lifted once the bar is fitted.' },
    { chapters: [
      { chapterNumber: 33, title: 'Bisik dari Dusun Bawah', paragraphs: ['Seorang pedagang menyebut pintu air dusun bawah mungkin ditutup lebih cepat bulan ini. Ia tidak tahu harinya. Vina menyimpan kabar itu sambil menimbang benih kering di atas timbangan gantung. Karena hujan turun cukup sering, ia meneruskan jadwal tanam yang lama dan membiarkan tempayan cadangan tetap kosong di sudut dapur.'] },
      { chapterNumber: 34, title: 'Cerita Tiga Penanam', paragraphs: ['Tiga penanam memberi waktu berbeda: besok, Jumat, atau setelah pasar. Vina menulis ketiganya di tepi buku memakai pensil pendek. Ia berjalan ke gerbang, namun bangku penjaga kosong dan sandalnya tertinggal di bawah. Pintu terbuka dan air mengalir sesuai giliran yang tertulis pada kartu jatah air.'] },
      { chapterNumber: 35, title: 'Papan Tidak Berubah', paragraphs: ['Papan jadwal masih memuat jam lama tanpa coretan. Vina menyalinnya ke balik nota untuk berjaga-jaga. Mbah Ripto berkata perintah dari kantor belum sampai ke tangannya. Ia menanam satu bedeng seperti rencana, sambil menyisakan setengah tampah benih kering bila aliran benar-benar berhenti lebih awal.'] },
      { chapterNumber: 36, title: 'Awan Menyimpan Cadangan', paragraphs: ['Hujan sore memenuhi dua tempayan, sehingga Vina memiliki cadangan kecil di bawah talang. Kabar penutupan kembali muncul di warung, kali ini tanpa sumber baru. Ia menutup tempayan dengan kain dan tetap mengirim benih kepada tetangga, sebab petaknya cukup basah untuk beberapa hari.'] },
      { chapterNumber: 37, title: 'Penjaga Belum Mendengar', paragraphs: ['Vina menemui penjaga gerbang bambu tua dan menanyakan perubahan. Lelaki itu menggeleng, lalu menunjukkan surat tugas lama. Ia berjanji memberi tahu jika perintah datang. Vina pulang melalui pematang, memanggul satu tempayan kosong yang tak perlu diisi hari itu. Vina mengulang pertanyaan sambil menunjukkan kartu.'] },
      { chapterNumber: 38, title: 'Satu Giliran Terlambat', paragraphs: ['Air datang lima belas menit terlambat karena ranting menyangkut kisi. Penjaga membersihkannya dan mengganti waktu yang hilang pada ujung giliran. Vina mencatat kejadian itu, tetapi tidak mengaitkannya dengan kabar penutupan. Semua bedeng memperoleh air sebelum senja. Danu mencatat jam air mencapai bedeng terakhir.'] },
      { chapterNumber: 39, title: 'Warung Menyebut Jumat', paragraphs: ['Pemilik warung yakin penutupan terjadi Jumat berdasarkan cerita seorang kru. Vina membeli teh dan bertanya nama kru tersebut; para peminum di bangku panjang saling melempar tebakan. Ia menambah satu baris catatan di buku, lalu pulang tanpa membatalkan penyaluran benih kering Sabtu. Vina menuliskan kabar itu pada balik nota.'] },
      { chapterNumber: 40, title: 'Jumat Berlalu Biasa', paragraphs: ['Jumat berlalu dengan pintu saluran terbuka menurut jadwal di papan. Vina memakai separuh cadangan tempayan untuk mencuci tampah anyaman. Penanam dusun bawah masih membicarakan kemungkinan pekan berikut sambil berjongkok di tepi jalan. Ia menyimpan sisa air hujan di bawah kain dan menunggu kabar yang lebih jelas.'] },
      { chapterNumber: 41, title: 'Kabar Dari Dusun Bawah', paragraphs: ['Seorang anak datang membawa kabar bahwa satu pintu air di dusun bawah mungkin akan ditutup lebih cepat. Vina menanyakan sumbernya, tetapi anak itu hanya mendengar orang dewasa berbicara di warung. Ia menyimpan berita itu tanpa membatalkan kerja menjemur benih. Tidak ada waktu atau nama yang dapat diperiksa, sehingga kabar tersebut belum mengubah apa yang dapat dilakukan hari itu.'] },
      { chapterNumber: 42, title: 'Anak Lupa Nama', paragraphs: ['Anak itu kembali, tetapi lupa siapa yang pertama berbicara di warung. Vina memberinya singkong rebus dan bertanya apakah ada surat. Ia menggeleng. Setelah anak pergi, Vina membalik benih kering di tampah anyaman bambu dan menutupnya sebelum embun turun. Bu Ningsih menyuruhnya mengingat warna pagar.'] },
      { chapterNumber: 43, title: 'Warung Tidak Membuka Jawaban', paragraphs: ['Vina mendatangi warung sore hari dan mendapat tiga cerita berbeda tentang pintu air yang sama. Seorang menyebut besok, seorang menyebut akhir minggu, dan seorang lagi mengatakan semua itu hanya gosip. Ia membeli teh, mendengarkan sampai gelap, lalu pulang dengan informasi yang tidak lebih tajam. Ketegangan bertambah sedikit karena kemungkinan itu masih ada, tetapi tidak ada tindakan mendesak yang bisa dipilihnya.'] },
      { chapterNumber: 44, title: 'Tempayan Diisi Separuh', paragraphs: ['Vina pagi-pagi mengisi satu tempayan sebagai cadangan, menghabiskan setengah jam setelah giliran. Ia terlambat mengantar benih kering ke rumah bambu dekat sekolah, namun pembeli masih menunggu di bangku teras. Perempuan itu membayar penuh dan memesan dua bungkus lagi untuk pekan depan, sedangkan petak Vina tetap basah oleh hujan lereng kemarin.'] },
      { chapterNumber: 45, title: 'Pesan Tanpa Cap', paragraphs: ['Secarik pesan muncul di pagar: pintu kayu mungkin ditutup satu jam awal esok. Tulisan itu tanpa nama dan cap. Vina memindahkan penyiraman dua bedeng ke pagi berkabut, meninggalkan satu tampah anyaman belum ditampi di teras. Ia meminta Danu membantu selepas kerja.'] },
      { chapterNumber: 46, title: 'Pintu Ditutup Satu Jam Awal', paragraphs: ['Pada hari ketiga pintu dusun bawah benar-benar ditutup satu jam lebih awal. Dua petak Vina menerima air lebih sedikit, namun hujan malam sebelumnya membuat tanaman tidak langsung layu. Ia menulis waktu penutupan di buku dan berjanji akan menanyakan alasan besok. Kerugian kecil itu memberi arah, tetapi belum membuat keterlambatan menjadi mahal atau pilihannya menjadi sempit.'] },
      { chapterNumber: 47, title: 'Alasan Ranting Besar', paragraphs: ['Penjaga mengatakan ranting besar merusak tuas sehingga pintu kayu ditutup awal. Ia menunjukkan kayu yang patah dan berjanji memperbaiki siang itu. Vina menyiram ujung petak memakai cadangan tempayan. Hanya satu baris tanaman menerima air lebih sedikit. Danu menunjukkan serpihan kayu pada Vina.'] },
      { chapterNumber: 48, title: 'Tuas Diganti Bambu', paragraphs: ['Tuas baru dari batang bambu dipasang dan diuji di depan warga. Pintu bergerak penuh. Vina mencatat waktu uji itu di bukunya, lalu kembali menampi benih kering yang tertunda. Danu membantu satu jam, sehingga pesanan selesai sebelum pasar berikutnya. Danu mengikat sambungan dengan tali goni, lalu mencobanya di depan penjaga.'] },
      { chapterNumber: 49, title: 'Daun Ujung Menguning', paragraphs: ['Beberapa daun pada baris paling ujung menguning, tetapi batangnya tetap tegak. Vina memotong bagian kering dan menyiramkan air sisa cucian ke pangkalnya. Pengepul menerima hasil petak lain dengan harga biasa dan membayar di tempat. Pada kartu jatah di sakunya, jam giliran tertulis serupa dengan bulan sebelumnya. Vina mencabut satu daun untuk diperiksa di rumah.'] },
      { chapterNumber: 50, title: 'Giliran Kembali Penuh', paragraphs: ['Pintu dibuka sesuai jadwal pada giliran berikut. Air mencapai dua petak hingga batas batu kali. Vina menutup buku setelah menambahkan catatan perbaikan pada baris terakhir. Satu baris daun basah masih pucat, sedangkan penanaman, penjualan, dan pembagian dusun berjalan kembali. Danu membuka alur menuju bedeng paling ujung.'] },
    ], justification: 'Bab 33–50 begins with conflicting rumours, prompts one small reserve and a shifted chore, then produces a single one-hour early closure. Rain and stored water buffer two plots; a bamboo repair restores the next turn, leaving only a few yellow leaves.' },
    { chapters: [
      { chapterNumber: 33, title: 'Bintik pada Satu Tampah', paragraphs: ['Vina melihat tiga butir berbintik pada satu tampah benih kering di dekat jendela. Ia mengambilnya dengan ujung pisau dan memisahkan segenggam ke dalam mangkuk tanah. Karung asal tampah itu masih berbau seperti jerami panas. Teras kosong sampai siang, maka selembar kain tenun ia bentangkan di atas tampah sebelum menyapu lantai papan.'] },
      { chapterNumber: 34, title: 'Mangkuk Ditaruh Jauh', paragraphs: ['Mangkuk contoh ditaruh jauh dari rak utama. Danu menyarankan membakarnya, tetapi Vina ingin Karsa memeriksanya lebih dulu. Pedagang itu dijadwalkan datang akhir pekan. Vina menandai tampah tersebut dengan garis arang, lalu menjual benih kering dari karung lain kepada satu keluarga.'] },
      { chapterNumber: 35, title: 'Bau Belum Berubah', paragraphs: ['Vina mencium tampah anyaman bambu setiap pagi berkabut dan tidak menemukan bau asam. Dua butir baru menunjukkan bercak. Ia memperlebar jarak dari tampah lain dan membuka jendela agar udara bergerak. Persediaan sehat masih memenuhi enam rak, cukup untuk pesanan berjalan.'] },
      { chapterNumber: 36, title: 'Karsa Mengirim Pesan', paragraphs: ['Seorang anak membawa pesan bahwa Karsa tertahan memperbaiki roda gerobak. Ia mungkin tiba tiga hari lagi. Vina membalik butir bercak itu dan menjemurnya terpisah di ujung teras. Satu pembeli pasar bertanya, lalu menerima jenis benih kering lain dengan harga sama tanpa keberatan. Vina menyimpan surat itu bersama nota pasar.'] },
      { chapterNumber: 37, title: 'Kain Penutup Dicuci', paragraphs: ['Kain penutup tampah berbau lembap setelah hujan lereng semalam. Vina mencucinya di tempayan belakang dan menggantinya dengan kain tenun kering. Pekerjaan itu memakan waktu satu jam, membuat makan siangnya terlambat. Benih pada enam rak lain tetap di tempatnya, dan daun pintu lumbung dibiarkan terbuka bagi pembeli.'] },
      { chapterNumber: 38, title: 'Bercak Bertambah Lima', paragraphs: ['Lima butir tambahan memperlihatkan titik hitam. Vina memindahkan seluruh tampah anyaman ke meja bambu teras dan menyelipkan nampan seng di bawahnya. Hujan tak mencapai meja. Ia mencatat jumlah, kemudian memenuhi dua pesanan dari tumpukan sehat sebelum petang dingin. Ia memisahkan butir sehat dengan sendok kayu.'] },
      { chapterNumber: 39, title: 'Roda Gerobak Belum Selesai', paragraphs: ['Pesan kedua menyebut roda Karsa belum selesai karena pandai besi sakit. Vina harus menunggu sampai hari pasar tiba. Ia menahan penjualan dari satu tampah anyaman saja. Seorang penanam memilih kembali Senin, sedangkan dua lainnya membeli varietas berbeda yang tersedia. Danu menyangga gerobak memakai bongkah batu.'] },
      { chapterNumber: 40, title: 'Satu Pembeli Menunggu', paragraphs: ['Penanam yang memilih menunggu menitipkan karcis pesan tanpa uang muka. Vina menyelipkan karcis itu di halaman pesanan agar nama keluarganya tetap terbaca dari tepi buku. Tampah bercak tinggal di teras, terpisah beberapa langkah dari enam rak sehat di dalam. Daun pintu lumbung ia buka lebar seperti pagi-pagi sebelumnya, dan timbangan gantung tetap dipakai melayani pembeli pasar.'] },
      { chapterNumber: 41, title: 'Bercak Hitam pada Benih', paragraphs: ['Vina melihat bercak hitam pada beberapa butir benih di satu tampah, lalu memisahkannya dari tumpukan utama. Karsa belum datang untuk memeriksa dan tidak ada rumah yang menunggu benih hari itu. Ia menutup tampah dengan kain tipis sambil mencatat jumlah kasar. Temuan tersebut mengganggu pikirannya, namun tidak menutup lumbung atau mengubah pembagian apa pun.'] },
      { chapterNumber: 42, title: 'Butir Dijemur Terpisah', paragraphs: ['Matahari terang memungkinkan Vina menjemur butir bercak di ujung halaman lumbung. Ia memakai tampah anyaman kecil agar tidak bercampur dengan jemuran lain. Seorang anak hampir menyentuhnya, lalu mundur ketika diperingatkan. Pesanan sehat diangkat pembeli pasar melalui pintu depan. Vina membaliknya saat sisi atas mulai kering.'] },
      { chapterNumber: 43, title: 'Karsa Tertahan di Pasar', paragraphs: ['Pesan dari Karsa tiba lewat anak pengantar: pedagang itu tertahan di pasar bawah sampai akhir pekan. Vina membalik benih bercak hitam setiap pagi dan mencium baunya, tetapi tidak punya cara memastikan penyebabnya. Ia memisahkan satu tampah lagi untuk berjaga-jaga. Persediaan masih cukup dan belum ada penanam yang ditolak, sehingga tekanan belum melewati kewaspadaan sehari-hari.'] },
      { chapterNumber: 44, title: 'Dua Tampah Menepi', paragraphs: ['Dua tampah terpisah memenuhi meja bambu teras, sehingga Vina memindahkan tempat minum ke dapur. Danu makan di tangga selama dua hari dengan piring di pangkuan. Butir dari karung lain masih berwarna cokelat rata ketika ditaburkan ke telapak. Vina mengeringkan pesanan utama di halaman depan lumbung, beralas tikar lebar.'] },
      { chapterNumber: 45, title: 'Pembeli Memilih Cadangan', paragraphs: ['Dua keluarga datang mencari varietas pada tampah anyaman bambu yang ditahan. Vina menawarkan cadangan musim lalu, tetapi keduanya menunjukkan semai lama di dalam keranjang. Setelah berbicara di teras, kedua keluarga memilih pulang dan kembali besok untuk menunggu hasil pemeriksaan tampah bercak.'] },
      { chapterNumber: 46, title: 'Dua Rumah Menunggu Besok', paragraphs: ['Dua rumah datang meminta benih pada sore hari, dan Vina meminta mereka kembali besok karena tampah bercak masih belum diperiksa. Mereka setuju tanpa marah sebab masing-masing masih memiliki cadangan semai. Vina kehilangan satu hari penyaluran, lalu menaruh tanda arang pada tampah. Risiko mulai menyentuh orang lain, tetapi jadwal dan hubungan belum pecah oleh keputusan itu.'] },
      { chapterNumber: 47, title: 'Karsa Tiba Berjalan', paragraphs: ['Karsa tiba berjalan kaki karena roda gerobaknya masih dilepas. Ia menggosok butir bercak, membelahnya, lalu mengatakan jamur hanya mengenai kulit sebagian benih kering. Ia menyarankan membuang dua tampah anyaman itu dan menyiram meja bambu dengan air panas. Vina menyodorkan bangku dan segelas air.'] },
      { chapterNumber: 48, title: 'Dua Tampah Dibakar', paragraphs: ['Vina membakar isi dua tampah anyaman bambu di tungku tanah luar. Asap pahit membuat matanya berair. Nilainya setara dua pesanan kecil. Karsa memeriksa enam rak lain dan tidak menemukan bercak, lalu menulis hasilnya pada karcis kedua keluarga yang menunggu. Abunya dikumpulkan jauh dari ruang penyimpanan.'] },
      { chapterNumber: 49, title: 'Cadangan Dibagi Dua', paragraphs: ['Vina membagi benih kering cadangan kepada dua keluarga dengan jumlah sedikit lebih kecil. Mereka menerimanya dan berjanji menukar kekurangan setelah panen. Keduanya berangkat menugal bedeng sore itu juga. Meja teras dibersihkan, sementara karung goni sehat kembali memenuhi pesanan pasar. Vina memberi label berbeda pada kedua keranjang.'] },
      { chapterNumber: 50, title: 'Meja Teras Dipakai Lagi', paragraphs: ['Setelah tiga hari memeriksa tanpa menemukan bercak baru, Vina memakai meja teras untuk makan kembali. Karsa datang dengan roda yang sudah terpasang dan membeli satu karung sehat dari rak tengah. Dua tampah telah hilang dari hitungan, tetapi daun pintu lumbung terbuka sejak pagi, pelanggan lama kembali menakar, dan penyaluran berjalan menurut buku pesanan.'] },
    ], justification: 'Bab 33–50 isolates a spotted tray, then a second, while Karsa’s delayed arrival makes two households wait one day. Both have reserve seedlings; two trays are burned and replaced with slightly smaller allotments, with no closure or wider crop loss.' },
  ],
}
